/* ---------------- Settings ---------------- */
typedef struct {
   char* name;
   int* fields; int nfields, capfields;
   int sort_key, tree_sort_key, sort_direction, tree_sort_direction;
   int tree_view, tree_view_always_by_pid, all_branches_collapsed;
} ScreenSettings;

typedef struct {
   int hide_kernel_threads, hide_userland_threads, hide_running_in_container;
   int shadow_other_users, show_thread_names, show_program_path;
   int highlight_base_name, highlight_deleted_exe, shadow_distribution_path_prefix;
   int highlight_megabytes, highlight_threads, highlight_changes, highlight_changes_delay_secs;
   int find_comm_in_cmdline, strip_exe_from_cmdline, show_merged_command;
   int header_margin, screen_tabs, detailed_cpu_time, cpu_count_from_one;
