   int account_guest_in_cpu_meter, color_scheme, enable_mouse, delay, hide_function_bar;
   char* header_layout;
   char*** meters; int* nmeters; int** meter_modes; int nmeter_cols;
   ScreenSettings* screens; int nscreens, capscreens;
   int changed;
} Settings;
static Settings S;
static char* config_path = NULL;

static void screen_add_field(ScreenSettings* sc, int fid){
   if(sc->nfields>=sc->capfields){ sc->capfields=sc->capfields?sc->capfields*2:16; sc->fields=xrealloc(sc->fields, sc->capfields*sizeof(int)); }
   sc->fields[sc->nfields++]=fid;
}
static ScreenSettings* settings_new_screen(const char* name){
   if(S.nscreens>=S.capscreens){ S.capscreens=S.capscreens?S.capscreens*2:4; S.screens=xrealloc(S.screens, S.capscreens*sizeof(ScreenSettings)); }
   ScreenSettings* sc=&S.screens[S.nscreens++]; memset(sc,0,sizeof(*sc)); sc->name=xstrdup(name);
   sc->sort_key=46; sc->tree_sort_key=0; sc->sort_direction=-1; sc->tree_sort_direction=1;
   return sc;
}
