   memset(&S,0,sizeof(S));
   S.hide_kernel_threads=1; S.hide_userland_threads=0; S.hide_running_in_container=0;
   S.shadow_other_users=0; S.show_thread_names=0; S.show_program_path=1;
   S.highlight_base_name=0; S.highlight_deleted_exe=1; S.shadow_distribution_path_prefix=0;
   S.highlight_megabytes=1; S.highlight_threads=1; S.highlight_changes=0; S.highlight_changes_delay_secs=5;
