   S.nmeter_cols=2; S.meters=xmalloc(2*sizeof(char**)); S.nmeters=xmalloc(2*sizeof(int)); S.meter_modes=xmalloc(2*sizeof(int*));
   const char* c0[]={"LeftCPUs8","Memory","Swap"}; const char* c1[]={"RightCPUs8","Tasks","LoadAverage","Uptime"};
   S.nmeters[0]=3; S.meters[0]=xmalloc(3*sizeof(char*)); S.meter_modes[0]=xmalloc(3*sizeof(int));
   for(int i=0;i<3;i++){ S.meters[0][i]=xstrdup(c0[i]); S.meter_modes[0][i]=1; }
   S.nmeters[1]=4; S.meters[1]=xmalloc(4*sizeof(char*)); S.meter_modes[1]=xmalloc(4*sizeof(int));
   for(int i=0;i<4;i++){ S.meters[1][i]=xstrdup(c1[i]); S.meter_modes[1][i]=(i==0?1:2); }
