static void make_default_screens(void){
   ScreenSettings* m=settings_new_screen("Main");
   int mf[]={0,48,17,18,38,39,40,2,46,47,49,1}; for(size_t i=0;i<sizeof(mf)/sizeof(int);i++) screen_add_field(m,mf[i]);
   ScreenSettings* io=settings_new_screen("I/O");
   int iof[]={0,48,114,111,109,110,1}; for(size_t i=0;i<sizeof(iof)/sizeof(int);i++) screen_add_field(io,iof[i]);
   io->sort_key=111; io->sort_direction=-1;
}
static int header_layout_cols(const char* s){
   if(!s) return 2;
   if(starts_with(s,"one")) return 1;
   if(starts_with(s,"two")) return 2;
   if(starts_with(s,"three")) return 3;
   if(starts_with(s,"four")) return 4;
   return 2;
}
static void header_layout_ratios(const char* s, double* r, int* n){
   *n=header_layout_cols(s);
   if(*n==1){ r[0]=1.0; }
   else if(*n==2){ if(strstr(s,"33_67")){r[0]=.33;r[1]=.67;} else if(strstr(s,"67_33")){r[0]=.67;r[1]=.33;} else {r[0]=.5;r[1]=.5;} }
   else if(*n==3){
      if(strstr(s,"25_25_50")){r[0]=.25;r[1]=.25;r[2]=.50;}
      else if(strstr(s,"25_50_25")){r[0]=.25;r[1]=.50;r[2]=.25;}
      else if(strstr(s,"50_25_25")){r[0]=.50;r[1]=.25;r[2]=.25;}
      else if(strstr(s,"40_30_30")){r[0]=.40;r[1]=.30;r[2]=.30;}
      else if(strstr(s,"30_40_30")){r[0]=.30;r[1]=.40;r[2]=.30;}
      else if(strstr(s,"30_30_40")){r[0]=.30;r[1]=.30;r[2]=.40;}
      else if(strstr(s,"40_20_40")){r[0]=.40;r[1]=.20;r[2]=.40;}
      else {r[0]=.33;r[1]=.34;r[2]=.33;}
   } else { for(int i=0;i<4;i++) r[i]=.25; }
}
/* ensure meters arrays cover layout columns */
static void ensure_meter_cols(void){
   int need=header_layout_cols(S.header_layout);
   if(need<=S.nmeter_cols) { /* keep extra? writer uses layout count only */ return; }
   S.meters=xrealloc(S.meters, need*sizeof(char**)); S.nmeters=xrealloc(S.nmeters, need*sizeof(int)); S.meter_modes=xrealloc(S.meter_modes, need*sizeof(int*));
   for(int i=S.nmeter_cols;i<need;i++){ S.meters[i]=NULL; S.nmeters[i]=0; S.meter_modes[i]=NULL; }
   S.nmeter_cols=need;
}

static char* determine_config_path(void){
   const char* h=getenv("HTOPRC");
   if(h && h[0]) return xstrdup(h);
   const char* xdg=getenv("XDG_CONFIG_HOME");
   if(xdg && xdg[0]){ char* p=NULL; if(asprintf(&p,"%s/htop/htoprc",xdg)<0) exit(1); return p; }
   const char* home=getenv("HOME"); if(!home) home="";
   char* p=NULL; if(asprintf(&p,"%s/.config/htop/htoprc",home)<0) exit(1); return p;
}
static void mkdirs_for_file(const char* path){
   char* tmp=xstrdup(path); char* slash=strrchr(tmp,'/');
   if(slash){ *slash=0; /* mkdir -p */
      for(char* p=tmp+1;*p;p++){ if(*p=='/'){ *p=0; mkdir(tmp,0755); *p='/'; } }
      mkdir(tmp,0755);
   }
   free(tmp);
}

/* helpers to split by spaces */
static char** split_spaces(const char* s, int* outn){
   *outn=0; if(!s) return NULL; char** arr=NULL; int cap=0;
   const char* p=s; while(*p){ while(*p && isspace((unsigned char)*p)) p++; if(!*p) break; const char* q=p; while(*q && !isspace((unsigned char)*q)) q++;
      if(*outn>=cap){ cap=cap?cap*2:8; arr=xrealloc(arr,cap*sizeof(char*)); }
      arr[(*outn)++]=xstrndup(p,q-p); p=q; }
   return arr;
}
static void set_meters_from_config(int col, const char* value, int is_modes){
   ensure_meter_cols(); if(col<0) return;
   // grow if needed
   if(col>=S.nmeter_cols){ int old=S.nmeter_cols; S.meters=xrealloc(S.meters,(col+1)*sizeof(char**)); S.nmeters=xrealloc(S.nmeters,(col+1)*sizeof(int)); S.meter_modes=xrealloc(S.meter_modes,(col+1)*sizeof(int*)); for(int i=old;i<=col;i++){S.meters[i]=NULL;S.nmeters[i]=0;S.meter_modes[i]=NULL;} S.nmeter_cols=col+1; }
   int n=0; char** toks=split_spaces(value,&n);
   if(!is_modes){
      for(int i=0;i<S.nmeters[col];i++) free(S.meters[col][i]); free(S.meters[col]); free(S.meter_modes[col]);
      S.nmeters[col]=n; S.meters[col]=toks; S.meter_modes[col]=xmalloc((n?n:1)*sizeof(int)); for(int i=0;i<n;i++) S.meter_modes[col][i]=1;
   } else {
      if(!S.meter_modes[col]) S.meter_modes[col]=xmalloc((S.nmeters[col]?S.nmeters[col]:1)*sizeof(int));
      // if modes set before meters, ensure size later? keep values in a temp by expanding
      if(n>S.nmeters[col]){ /* modes arrived first: store as modes array length n, meters will reallocate preserving? Simplify: keep modes values and resize later in ensure */ }
      for(int i=0;i<n && i<S.nmeters[col];i++) S.meter_modes[col][i]=atoi(toks[i]);
      // store extra in case meters not yet parsed: encode by expanding nmeters placeholder not desired; handle order usually meters first
      for(int i=0;i<n;i++) free(toks[i]); free(toks);
   }
}

static void settings_read(void){
   config_path=determine_config_path();
   settings_defaults();
   FILE* f=fopen(config_path,"r");
   int have_file=0, nonempty=0;
   if(f){ struct stat st; if(stat(config_path,&st)==0 && st.st_size>0) nonempty=1; have_file=1; }
   const char* syscfg="/etc/htoprc";
   if(!f && access(syscfg,R_OK)==0){ f=fopen(syscfg,"r"); if(f){ have_file=1; nonempty=1; } }
   if(!f || !nonempty){
      if(f) fclose(f);
      S.screen_tabs=1; S.changed=1;
      make_default_screens();
      return;
   }
   S.changed=0;
   // global legacy values
   int g_fields[512]; int g_nfields=0; int have_g_fields=0;
   int g_sort_key=46, g_tree_sort_key=0, g_sort_dir=-1, g_tree_sort_dir=1, g_tree_view=0, g_tree_always=0, g_collapsed=0;
   int have_g_sort=0;
   ScreenSettings* cur=NULL;
   char* line=NULL; size_t cap=0; ssize_t len;
   while((len=getline(&line,&cap,f))>=0){
      while(len>0 && (line[len-1]=='\n' || line[len-1]=='\r')) line[--len]=0;
      if(line[0]=='#' || line[0]==0) continue;
      char* eq=strchr(line,'='); if(!eq) continue; *eq=0; const char* key=line; const char* val=eq+1;
      if(strcmp(key,"fields")==0){ have_g_fields=1; g_nfields=0; int n=0; char** t=split_spaces(val,&n); for(int i=0;i<n;i++){ int id=atoi(t[i]); if(field_by_id(id) && g_nfields<512) g_fields[g_nfields++]=id; free(t[i]); } free(t); }
      else if(strcmp(key,"sort_key")==0){ g_sort_key=atoi(val); have_g_sort=1; }
      else if(strcmp(key,"tree_sort_key")==0) g_tree_sort_key=atoi(val);
      else if(strcmp(key,"sort_direction")==0) g_sort_dir=atoi(val);
      else if(strcmp(key,"tree_sort_direction")==0) g_tree_sort_dir=atoi(val);
      else if(strcmp(key,"tree_view")==0) g_tree_view=atoi(val);
      else if(strcmp(key,"tree_view_always_by_pid")==0) g_tree_always=atoi(val);
      else if(strcmp(key,"all_branches_collapsed")==0) g_collapsed=atoi(val);
      else if(starts_with(key,"screen:")){
         cur=settings_new_screen(key+7);
         int n=0; char** t=split_spaces(val,&n); for(int i=0;i<n;i++){ const FieldDef* d=field_by_name(t[i]); if(d) screen_add_field(cur,d->id); free(t[i]); } free(t);
         // defaults for a screen in file
         cur->sort_key=46; cur->sort_direction=-1; cur->tree_sort_key=0; cur->tree_sort_direction=1;
         if(strcmp(cur->name,"I/O")==0){ cur->sort_key=111; }
      }
      else if(key[0]=='.' && cur){
         const char* k=key+1;
         if(strcmp(k,"sort_key")==0){ const FieldDef* d=field_by_name(val); if(d) cur->sort_key=d->id; }
         else if(strcmp(k,"tree_sort_key")==0){ const FieldDef* d=field_by_name(val); if(d) cur->tree_sort_key=d->id; }
         else if(strcmp(k,"sort_direction")==0) cur->sort_direction=atoi(val);
         else if(strcmp(k,"tree_sort_direction")==0) cur->tree_sort_direction=atoi(val);
         else if(strcmp(k,"tree_view")==0) cur->tree_view=atoi(val);
         else if(strcmp(k,"tree_view_always_by_pid")==0) cur->tree_view_always_by_pid=atoi(val);
         else if(strcmp(k,"all_branches_collapsed")==0) cur->all_branches_collapsed=atoi(val);
      }
      else if(starts_with(key,"screen:")){}
      else if(strcmp(key,"hide_kernel_threads")==0) S.hide_kernel_threads=atoi(val);
      else if(strcmp(key,"hide_userland_threads")==0) S.hide_userland_threads=atoi(val);
      else if(strcmp(key,"hide_running_in_container")==0) S.hide_running_in_container=atoi(val);
      else if(strcmp(key,"shadow_other_users")==0) S.shadow_other_users=atoi(val);
      else if(strcmp(key,"show_thread_names")==0) S.show_thread_names=atoi(val);
      else if(strcmp(key,"show_program_path")==0) S.show_program_path=atoi(val);
      else if(strcmp(key,"highlight_base_name")==0) S.highlight_base_name=atoi(val);
      else if(strcmp(key,"highlight_deleted_exe")==0) S.highlight_deleted_exe=atoi(val);
      else if(strcmp(key,"shadow_distribution_path_prefix")==0) S.shadow_distribution_path_prefix=atoi(val);
      else if(strcmp(key,"highlight_megabytes")==0) S.highlight_megabytes=atoi(val);
      else if(strcmp(key,"highlight_threads")==0) S.highlight_threads=atoi(val);
      else if(strcmp(key,"highlight_changes")==0) S.highlight_changes=atoi(val);
      else if(strcmp(key,"highlight_changes_delay_secs")==0) S.highlight_changes_delay_secs=atoi(val);
      else if(strcmp(key,"find_comm_in_cmdline")==0) S.find_comm_in_cmdline=atoi(val);
      else if(strcmp(key,"strip_exe_from_cmdline")==0) S.strip_exe_from_cmdline=atoi(val);
      else if(strcmp(key,"show_merged_command")==0) S.show_merged_command=atoi(val);
      else if(strcmp(key,"header_margin")==0) S.header_margin=atoi(val);
      else if(strcmp(key,"screen_tabs")==0) S.screen_tabs=atoi(val);
      else if(strcmp(key,"detailed_cpu_time")==0) S.detailed_cpu_time=atoi(val);
      else if(strcmp(key,"cpu_count_from_one")==0) S.cpu_count_from_one=atoi(val);
      else if(strcmp(key,"show_cpu_usage")==0) S.show_cpu_usage=atoi(val);
      else if(strcmp(key,"show_cpu_frequency")==0) S.show_cpu_frequency=atoi(val);
      else if(strcmp(key,"show_cached_memory")==0) S.show_cached_memory=atoi(val);
