      else if(strcmp(key,"header_layout")==0){ free(S.header_layout); S.header_layout=xstrdup(val); }
      else if(starts_with(key,"column_meters_")){ int col=atoi(key+strlen("column_meters_")); set_meters_from_config(col,val,0); }
