      else if(strcmp(key,"color_scheme")==0) S.color_scheme=atoi(val);
      // unknown keys ignored
   }
   free(line); fclose(f);
   ensure_meter_cols();
   if(S.nscreens==0){
      ScreenSettings* m=settings_new_screen("Main");
      if(have_g_fields){ for(int i=0;i<g_nfields;i++) screen_add_field(m,g_fields[i]); }
      else { int mf[]={0,48,17,18,38,39,40,2,46,47,49,1}; for(size_t i=0;i<sizeof(mf)/sizeof(int);i++) screen_add_field(m,mf[i]); }
