      char name[64]; unsigned long long v; if(sscanf(line,"%63[^:]: %llu",name,&v)!=2) continue;
      if(!strcmp(name,"MemTotal"))mem_total_kb=v; else if(!strcmp(name,"MemFree"))mem_free_kb=v; else if(!strcmp(name,"MemAvailable"))mem_available_kb=v; else if(!strcmp(name,"Buffers"))mem_buffers_kb=v; else if(!strcmp(name,"Cached"))mem_cached_kb=v; else if(!strcmp(name,"Shmem"))mem_shared_kb=v; else if(!strcmp(name,"SwapTotal"))swap_total_kb=v; else if(!strcmp(name,"SwapFree"))swap_free_kb=v; else if(!strcmp(name,"SwapCached"))swap_cached_kb=v; else if(!strcmp(name,"SReclaimable"))sreclaim_kb=v;
   } free(mi); }
