}

static char* get_username(int uid){
   struct passwd* pw=getpwuid(uid); if(pw && pw->pw_name) return xstrdup(pw->pw_name);
   char b[32]; snprintf(b,sizeof b,"%d",uid); return xstrdup(b);
}
static char* basename_dup(const char* p){ if(!p) return xstrdup("N/A"); const char* s=strrchr(p,'/'); return xstrdup(s?s+1:p); }

static void format_size_kb(char* buf,size_t n,unsigned long long kb){
   if(kb < 100000ULL){ snprintf(buf,n,"%llu",kb); return; }
   double mib=(double)kb/1024.0;
   if(mib < 100.0){ snprintf(buf,n,"%.1fM",mib); return; }
   if(mib < 10000.0){ snprintf(buf,n,"%.0fM",mib); return; }
   double gib=mib/1024.0;
   if(gib < 10.0) snprintf(buf,n,"%.2fG",gib);
   else if(gib < 100.0) snprintf(buf,n,"%.1fG",gib);
   else if(gib < 10000.0) snprintf(buf,n,"%.0fG",gib);
   else { double tib=gib/1024.0; if(tib<10) snprintf(buf,n,"%.2fT",tib); else if(tib<100) snprintf(buf,n,"%.1fT",tib); else snprintf(buf,n,"%.0fT",tib); }
}
static void format_bytes_size(char* buf,size_t n,unsigned long long bytes){
   // used for IO byte counters: original displays them scaled like sizes (in KiB-ish units when large)
   if(bytes < 100000ULL){ snprintf(buf,n,"%llu",bytes); return; }
   format_size_kb(buf,n,bytes/1024);
}
static void format_rate(char* buf,size_t n,double rate){
   if(rate < 0) rate=0;
   if(rate < 1000.0){ snprintf(buf,n,"%.2f B/s",rate); return; }
   double k=rate/1024.0; if(k < 1000.0){ if(k<10) snprintf(buf,n,"%.2f K/s",k); else if(k<100) snprintf(buf,n,"%.1f K/s",k); else snprintf(buf,n,"%.0f K/s",k); return; }
   double m=k/1024.0; if(m < 1000.0){ if(m<10) snprintf(buf,n,"%.2f M/s",m); else if(m<100) snprintf(buf,n,"%.1f M/s",m); else snprintf(buf,n,"%.0f M/s",m); return; }
   double g=m/1024.0; if(g<10) snprintf(buf,n,"%.2f G/s",g); else if(g<100) snprintf(buf,n,"%.1f G/s",g); else snprintf(buf,n,"%.0f G/s",g);
}
static void format_time_ticks(char* buf,size_t n,unsigned long long ticks){
   double secs=(double)ticks/(double)hz; unsigned long long total=(unsigned long long)secs;
   if(total < 3600){ unsigned long long mins=total/60; unsigned long long sec=total%60; unsigned long long cent=(unsigned long long)((secs - (double)total)*100.0 + 0.5); if(cent>=100){cent=0;sec++;} snprintf(buf,n,"%llu:%02llu.%02llu",mins,sec,cent); }
   else if(total < 3600ULL*100ULL){ unsigned long long h=total/3600; unsigned long long m=(total%3600)/60; unsigned long long sec=total%60; snprintf(buf,n,"%llu:%02llu:%02llu",h,m,sec); }
   else { snprintf(buf,n,"%lluh", total/3600); }
}
static void format_time_interval(char* buf,size_t n,double secs_d){
   if(secs_d<0) secs_d=0; unsigned long long total=(unsigned long long)secs_d;
   if(total < 3600){ unsigned long long mins=total/60; unsigned long long sec=total%60; unsigned long long cent=(unsigned long long)((secs_d - (double)total)*100.0 + 0.5); if(cent>=100){cent=0;sec++; if(sec>=60){sec=0;mins++;}} snprintf(buf,n,"%llu:%02llu.%02llu",mins,sec,cent); }
   else if(total < 3600ULL*100ULL){ unsigned long long h=total/3600; unsigned long long m=(total%3600)/60; unsigned long long sec=total%60; snprintf(buf,n,"%llu:%02llu:%02llu",h,m,sec); }
   else { snprintf(buf,n,"%lluh", total/3600); }
}

/* forward settings */
