   char* rest=rp+1; while(*rest==' ') rest++;
   char* fields[60]; int nf=0; char* save=NULL; for(char* tok=strtok_r(rest," ",&save); tok && nf<60; tok=strtok_r(NULL," ",&save)) fields[nf++]=tok;
   if(nf<20){ free(txt); free(comm); return 0; }
   pr->pid=pid; pr->comm=comm;
   pr->state=fields[0][0]; pr->ppid=atoi(fields[1]); pr->pgrp=atoi(fields[2]); pr->session=atoi(fields[3]); pr->tty_nr=atoi(fields[4]); pr->tpgid=atoi(fields[5]);
   pr->flags=strtoull(fields[6],NULL,10); pr->minflt=strtoull(fields[7],NULL,10); pr->cminflt=strtoull(fields[8],NULL,10); pr->majflt=strtoull(fields[9],NULL,10); pr->cmajflt=strtoull(fields[10],NULL,10);
   pr->utime=strtoull(fields[11],NULL,10); pr->stime=strtoull(fields[12],NULL,10); pr->cutime=strtoll(fields[13],NULL,10); pr->cstime=strtoll(fields[14],NULL,10);
   pr->priority=strtol(fields[15],NULL,10); pr->nice=strtol(fields[16],NULL,10); pr->num_threads=strtol(fields[17],NULL,10);
   pr->starttime_ticks=strtoull(fields[19],NULL,10); pr->vsize_bytes=strtoull(fields[20],NULL,10); pr->rss_pages=strtol(fields[21],NULL,10);
