static void fill_proc_extra(Proc* pr, int owner_pid, int need_pss){
   char path[256];
   pr->tgid=owner_pid;
   // statm from owner (memory shared)
   snprintf(path,sizeof path,"/proc/%d/statm",owner_pid); char* sm=read_file(path,NULL);
   if(sm){ unsigned long long a[7]={0}; sscanf(sm,"%llu %llu %llu %llu %llu %llu %llu",&a[0],&a[1],&a[2],&a[3],&a[4],&a[5],&a[6]); pr->statm_size=a[0]; pr->statm_res=a[1]; pr->statm_shared=a[2]; pr->statm_text=a[3]; pr->statm_lib=a[4]; pr->statm_data=a[5]; free(sm); }
