   pr->uid=0; pr->ctxt=0; pr->swap_kb=0;
   snprintf(path,sizeof path,"/proc/%d/status",owner_pid); char* status=read_file(path,NULL);
   int status_uid_set=0;
   if(status){ char* save=NULL; for(char* line=strtok_r(status,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
      if(starts_with(line,"Uid:")){ pr->uid=atoi(line+4); status_uid_set=1; }
      else if(starts_with(line,"VmSwap:")) pr->swap_kb=strtoull(line+7,NULL,10);
      else if(starts_with(line,"voluntary_ctxt_switches:")) pr->ctxt += strtoull(line+24,NULL,10);
      else if(starts_with(line,"nonvoluntary_ctxt_switches:")) pr->ctxt += strtoull(line+27,NULL,10);
   } free(status); }
   if(!status_uid_set){ struct stat st; snprintf(path,sizeof path,"/proc/%d",owner_pid); if(stat(path,&st)==0) pr->uid=st.st_uid; }
   pr->user=get_username(pr->uid);
   // cmdline
   snprintf(path,sizeof path,"/proc/%d/cmdline",owner_pid); size_t clen=0; char* cl=read_file(path,&clen);
   if(cl && clen>0){ // join NULs with spaces
      char* out=NULL; size_t olen=0,ocap=0; size_t i=0;
      while(i<clen){ size_t j=i; while(j<clen && cl[j]) j++; if(j>i){ if(olen) strbuf_append(&out,&olen,&ocap," "); strbuf_append(&out,&olen,&ocap,cl+i); } i=j+1; }
      if(!out) out=xstrdup("");
      pr->cmdline=out; free(cl);
   } else { if(cl) free(cl); pr->cmdline=xstrdup(""); }
   // comm file overrides? comm already from stat; for thread names use task comm later by caller if needed
   // exe/cwd
   snprintf(path,sizeof path,"/proc/%d/exe",owner_pid); char buf[4096]; ssize_t r=readlink(path,buf,sizeof(buf)-1); if(r>0){ buf[r]=0; pr->exe=xstrdup(buf); } else pr->exe=xstrdup("N/A");
   pr->exebase=basename_dup(strcmp(pr->exe,"N/A")==0?NULL:pr->exe); if(strcmp(pr->exe,"N/A")==0){ free(pr->exebase); pr->exebase=xstrdup("N/A"); }
   snprintf(path,sizeof path,"/proc/%d/cwd",owner_pid); r=readlink(path,buf,sizeof(buf)-1); if(r>0){ buf[r]=0; pr->cwd=xstrdup(buf); } else pr->cwd=xstrdup("N/A");
   // cgroup
   pr->cgroup=xstrdup("/"); pr->ccgroup=xstrdup("/"); pr->container=xstrdup("/"); pr->is_container=0;
   snprintf(path,sizeof path,"/proc/%d/cgroup",owner_pid); char* cg=read_file(path,NULL);
   if(cg){ char* chosen=NULL; char* save=NULL; for(char* line=strtok_r(cg,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){ char* c1=strchr(line,':'); if(!c1) continue; char* c2=strchr(c1+1,':'); if(!c2) continue; const char* pth=c2+1; if(!chosen || strcmp(pth,"/")!=0) { free(chosen); chosen=xstrdup(pth);} }
      if(chosen){ free(pr->cgroup); pr->cgroup=chosen; }
      free(cg);
      free(pr->ccgroup); pr->ccgroup=xstrdup(pr->cgroup);
      // compressed: strip common slice prefixes
      // container guessing
      const char* cgstr=pr->cgroup;
      if(strstr(cgstr,"docker")||strstr(cgstr,"kubepods")||strstr(cgstr,"libpod")||strstr(cgstr,"containerd")) pr->is_container=1;
      else {
         // a long hex component suggests container
         const char* p=cgstr; while(*p){ const char* s=strchr(p,'/'); size_t ln=s? (size_t)(s-p):strlen(p); if(ln>=32){ int hex=1; for(size_t i=0;i<ln;i++) if(!isxdigit((unsigned char)p[i])) hex=0; if(hex) pr->is_container=1; } if(!s) break; p=s+1; }
      }
      if(pr->is_container){ free(pr->container); // last path component truncated
         const char* last=strrchr(cgstr,'/'); const char* name=last?last+1:cgstr; if(!name[0]) name=cgstr; pr->container=xstrndup(name, MIN(strlen(name),(size_t)12)); }
      else { free(pr->container); pr->container=xstrdup(pr->cgroup); }
   }
   // oom
   pr->oom=0; snprintf(path,sizeof path,"/proc/%d/oom_score",owner_pid); unsigned long long ov; if(read_ull_file(path,&ov)) pr->oom=(long)ov;
   // secattr
   snprintf(path,sizeof path,"/proc/%d/attr/current",owner_pid); char* sa=read_file(path,NULL); if(sa){ size_t l=strlen(sa); while(l && (sa[l-1]=='\n'||sa[l-1]==0)) sa[--l]=0; if(l==0){ free(sa); sa=xstrdup("-"); } pr->secattr=sa; } else pr->secattr=xstrdup("-");
   // autogroup
   pr->autogroup_id=0; pr->autogroup_nice=0; snprintf(path,sizeof path,"/proc/%d/autogroup",owner_pid); char* ag=read_file(path,NULL); if(ag){ char* dash=strchr(ag,'-'); if(dash) pr->autogroup_id=atoi(dash+1); char* np=strstr(ag,"nice "); if(np) pr->autogroup_nice=atoi(np+5); free(ag); }
