   if(pr->policy<0) pr->policy=0;
   // io
   pr->io_avail=0; snprintf(path,sizeof path,"/proc/%d/io",owner_pid); char* io=read_file(path,NULL);
   if(io){ pr->io_avail=1; char* save=NULL; for(char* line=strtok_r(io,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
      if(starts_with(line,"rchar:")) pr->rchar=strtoull(line+6,NULL,10);
      else if(starts_with(line,"wchar:")) pr->wchar=strtoull(line+6,NULL,10);
      else if(starts_with(line,"syscr:")) pr->syscr=strtoull(line+6,NULL,10);
      else if(starts_with(line,"syscw:")) pr->syscw=strtoull(line+6,NULL,10);
      else if(starts_with(line,"read_bytes:")) pr->rbytes=strtoull(line+11,NULL,10);
      else if(starts_with(line,"write_bytes:")) pr->wbytes=strtoull(line+12,NULL,10);
      else if(starts_with(line,"cancelled_write_bytes:")) pr->cnclwb=strtoull(line+22,NULL,10);
   } free(io); }
   // ioprio via syscall (252 on x86_64)
   pr->io_class=0; pr->io_level=4;
#ifdef SYS_ioprio_get
   { long v=syscall(SYS_ioprio_get,1,pr->pid); if(v>=0){ pr->io_class=(v>>13)&7; pr->io_level=v&7; } }
#endif
   // pss
