   if(need_pss){
      snprintf(path,sizeof path,"/proc/%d/smaps_rollup",owner_pid); char* sr=read_file(path,NULL);
      if(sr){ char* save=NULL; for(char* line=strtok_r(sr,"\n",&save); line; line=strtok_r(NULL,"\n",&save)){
         if(starts_with(line,"Pss:")) pr->pss_kb=strtoull(line+4,NULL,10);
         else if(starts_with(line,"SwapPss:")) pr->psswp_kb=strtoull(line+8,NULL,10);
      } free(sr); }
      else { // fallback use resident
         pr->pss_kb=pr->rss_pages>0 ? (unsigned long long)pr->rss_pages*page_kb : 0;
      }
   } else {
      pr->pss_kb=pr->rss_pages>0 ? (unsigned long long)pr->rss_pages*page_kb : 0;
   }
   pr->priv_kb=0; { unsigned long long res=pr->rss_pages>0?(unsigned long long)pr->rss_pages*page_kb:0; unsigned long long shr=pr->statm_shared*page_kb; pr->priv_kb=res>shr?res-shr:0; }
   pr->is_kernel = (pr->vsize_bytes==0 && pr->cmdline[0]==0 && pr->state!='Z' && (pr->pid==2 || pr->ppid==2));
   pr->start_epoch = boot_time ? (double)boot_time + (double)pr->starttime_ticks/(double)hz : 0;
   pr->elapsed = wall_now_double() - pr->start_epoch; if(pr->elapsed<0) pr->elapsed=0;
}
EOF
"}

