   closedir(d);
   // sort pidlist ascending
   for(int i=0;i<npids;i++) for(int j=i+1;j<npids;j++) if(pidlist[j]<pidlist[i]){int t=pidlist[i];pidlist[i]=pidlist[j];pidlist[j]=t;}
   // new prevs to be built
   Prev* newprevs=NULL; int nnew=0, capnew=0;
   for(int pi=0;pi<npids;pi++){
      int pid=pidlist[pi]; char path[256]; snprintf(path,sizeof path,"/proc/%d/stat",pid);
      Proc tmp; memset(&tmp,0,sizeof(tmp));
      if(!parse_proc_stat(path,&tmp,pid)) continue;
      // fill extras based on owner
      Proc* pr=NULL;
      // append placeholder in procs (may be skipped after filtering, but we need stats for counts)
      total_tasks++;
      int nlwp=(int)tmp.num_threads; if(nlwp>1 && tmp.state!='Z') total_threads_extra += (nlwp-1);
      // We'll fill extras only for this process first
      Proc owner_extra; memset(&owner_extra,0,sizeof(owner_extra));
      // Instead, fill tmp extras directly (owner = pid)
      fill_proc_extra(&tmp,pid,need_pss);
      tmp.tgid=pid; tmp.is_thread=0;
      if(tmp.is_kernel) total_kthreads++;
      tmp.total_ticks=tmp.utime+tmp.stime;
      // cpu percent
      Prev* pv=prev_find(pid,tmp.starttime_ticks);
      if(pv){ double dt=ts-pv->ts; if(dt>0.000001){ tmp.cpu_percent=100.0*((double)(tmp.total_ticks-pv->cpu_ticks)/(double)hz)/dt; } else tmp.cpu_percent=0;
         tmp.ctxt_delta = tmp.ctxt>=pv->ctxt? tmp.ctxt-pv->ctxt:0;
         if(tmp.io_avail && pv){ if(dt>0.000001){ tmp.io_read_rate=(double)(tmp.rbytes>=pv->rbytes? tmp.rbytes-pv->rbytes:0)/dt; tmp.io_write_rate=(double)(tmp.wbytes>=pv->wbytes? tmp.wbytes-pv->wbytes:0)/dt; } tmp.io_rate=tmp.io_read_rate+tmp.io_write_rate; }
      } else {
         // first time we see this process: lifetime average since its start if started recently, else 0 approximated
         // Use start_epoch elapsed as denominator when elapsed is small (< 5 min) to get a sensible initial value, else interval fallback 0
         if(tmp.elapsed>0.05 && tmp.elapsed<300){ tmp.cpu_percent=100.0*((double)tmp.total_ticks/(double)hz)/tmp.elapsed; if(tmp.cpu_percent>100*num_cpus) tmp.cpu_percent=0; }
         else tmp.cpu_percent=0;
         tmp.ctxt_delta=0; tmp.io_read_rate=0; tmp.io_write_rate=0; tmp.io_rate=0;
      }
      // add to newprevs
      if(nnew>=capnew){capnew=capnew?capnew*2:256; newprevs=xrealloc(newprevs,capnew*sizeof(Prev));}
      newprevs[nnew].pid=pid; newprevs[nnew].starttime=tmp.starttime_ticks; newprevs[nnew].cpu_ticks=tmp.total_ticks; newprevs[nnew].ts=ts; newprevs[nnew].rbytes=tmp.rbytes; newprevs[nnew].wbytes=tmp.wbytes; newprevs[nnew].ctxt=tmp.ctxt; newprevs[nnew].seen=1; nnew++;
      tmp.display_cmd=build_display_cmd(&tmp,NULL,NULL);
      // placeholder for tree prefix
      tmp.tree_prefix=xstrdup("");
      // append to procs array
      if(nprocs>=capprocs){ capprocs=capprocs?capprocs*2:256; procs=xrealloc(procs,capprocs*sizeof(Proc)); }
      procs[nprocs++]=tmp;
      // threads
      if(!S.hide_userland_threads){
         char tdir[256]; snprintf(tdir,sizeof tdir,"/proc/%d/task",pid); DIR* td=opendir(tdir);
         if(td){ struct dirent* te; while((te=readdir(td))!=NULL){ if(!isdigit((unsigned char)te->d_name[0])) continue; int tid=atoi(te->d_name); if(tid==pid) continue;
            char tpath[256]; snprintf(tpath,sizeof tpath,"/proc/%d/task/%d/stat",pid,tid);
            Proc th; memset(&th,0,sizeof(th)); if(!parse_proc_stat(tpath,&th,pid)) continue;
            // fill from owner, but pid/tid specific values come from th stat (utime etc already parsed)
            // Save comm of thread
            char* thread_comm=th.comm? xstrdup(th.comm):NULL;
            // fill extras using owner pid for memory/cmd, but keep th's own stat fields
            // Temporarily stash numeric fields
            Proc saved=th; // shallow copy (comm pointer owned)
            // fill_proc_extra will set user/cmd etc based on owner, and policy via sched_getscheduler(th.pid) (it uses pr->pid so ok)
            // It also overwrites? It sets tgid etc, start_epoch from starttime (thread start)
            fill_proc_extra(&th,pid,need_pss);
            // Restore thread-specific totals: fill did not change utime/stime/priority/nice etc except policy and processor already from stat
            th.total_ticks=th.utime+th.stime;
            th.is_thread=1; th.tgid=pid;
            Prev* tpv=prev_find(tid,th.starttime_ticks);
            if(tpv){ double dt=ts-tpv->ts; if(dt>0.000001) th.cpu_percent=100.0*((double)(th.total_ticks-tpv->cpu_ticks)/(double)hz)/dt; else th.cpu_percent=0; th.ctxt_delta= th.ctxt>=tpv->ctxt? th.ctxt-tpv->ctxt:0; }
            else { if(th.elapsed>0.05 && th.elapsed<300){ th.cpu_percent=100.0*((double)th.total_ticks/(double)hz)/th.elapsed; } else th.cpu_percent=0; }
            if(nnew>=capnew){capnew=capnew?capnew*2:256; newprevs=xrealloc(newprevs,capnew*sizeof(Prev));}
            newprevs[nnew].pid=tid; newprevs[nnew].starttime=th.starttime_ticks; newprevs[nnew].cpu_ticks=th.total_ticks; newprevs[nnew].ts=ts; newprevs[nnew].rbytes=th.rbytes; newprevs[nnew].wbytes=th.wbytes; newprevs[nnew].ctxt=th.ctxt; newprevs[nnew].seen=1; nnew++;
            // display cmd: if show_thread_names and thread name differs, show thread_comm, else owner's cmd
            if(S.show_thread_names && thread_comm && saved.comm && strcmp(thread_comm,tmp.comm)!=0){ th.display_cmd=xstrdup(thread_comm); }
            else th.display_cmd=build_display_cmd(&th,NULL,thread_comm);
            // comm for thread row should be thread name
            if(thread_comm){ free(th.comm); th.comm=xstrdup(thread_comm); }
            free(thread_comm);
            th.tree_prefix=xstrdup("");
            if(nprocs>=capprocs){ capprocs=capprocs?capprocs*2:256; procs=xrealloc(procs,capprocs*sizeof(Proc)); }
            procs[nprocs++]=th;
            (void)saved;
         } closedir(td); }
      }
   }
   free(prevs); prevs=newprevs; nprevs=nnew; capprevs=capnew;
   last_scan_time=ts;
}

/* sorting */
static ScreenSettings* cur_screen(void){ if(S.nscreens==0) return NULL; if(current_screen_idx<0) current_screen_idx=0; if(current_screen_idx>=S.nscreens) current_screen_idx=0; return &S.screens[current_screen_idx]; }
