   if(sc->tree_view){ if(dir_out) *dir_out=sc->tree_sort_direction; return sc->tree_sort_key; }
   if(dir_out) *dir_out=sc->sort_direction; return sc->sort_key;
}
static double proc_sort_value_num(Proc* p,int key){
   switch(key){
      case 0: return p->pid; case 3: return p->ppid; case 4: return p->pgrp; case 5: return p->session; case 7: return p->tpgid;
      case 9: return (double)p->minflt; case 10: return (double)p->cminflt; case 11: return (double)p->majflt; case 12: return (double)p->cmajflt;
      case 13: return (double)p->utime; case 14: return (double)p->stime; case 15: return (double)p->cutime; case 16: return (double)p->cstime;
      case 17: return p->priority; case 18: return p->nice; case 20: return p->start_epoch; case 37: return p->processor;
