      case 41: return (double)p->statm_text*(double)page_kb; case 42: return (double)p->statm_data*(double)page_kb; case 43: return (double)p->statm_lib*(double)page_kb;
      case 45: return p->uid; case 46: return p->cpu_percent; case 52: return num_cpus?p->cpu_percent/num_cpus:0; case 47: { double m=mem_total_kb?(double)(p->rss_pages>0?p->rss_pages:0)*page_kb*100.0/mem_total_kb:0; return m; }
      case 49: return (double)p->total_ticks; case 50: return p->num_threads; case 51: return p->tgid; case 53: return p->elapsed; case 54: return p->policy;
      case 102: return (double)p->rchar; case 103: return (double)p->wchar; case 104: return (double)p->syscr; case 105: return (double)p->syscw;
