      case 109: return p->io_read_rate; case 110: return p->io_write_rate; case 111: return p->io_rate;
      case 113: return p->oom; case 114: return p->io_class*100+p->io_level; case 118: return (double)p->pss_kb; case 119: return (double)p->swap_kb; case 120: return (double)p->psswp_kb; case 121: return (double)p->ctxt_delta;
      case 126: return p->autogroup_id; case 127: return p->autogroup_nice; case 130: return (double)p->priv_kb; case 131: return 0; case 132: return 0; case 133: return p->is_container;
      default: return p->pid;
   }
