static const char* proc_sort_value_str(Proc* p,int key){
   switch(key){
      case 1: return p->display_cmd?p->display_cmd:""; case 2: { static char b[2]; b[0]=p->state;b[1]=0; return b; }
      case 6: return ""; case 48: return p->user?p->user:""; case 112: return p->cgroup?p->cgroup:""; case 122: return p->secattr?p->secattr:"";
      case 123: return p->comm?p->comm:""; case 124: return p->exebase?p->exebase:""; case 125: return p->cwd?p->cwd:""; case 128: return p->ccgroup?p->ccgroup:""; case 129: return p->container?p->container:"";
      default: return p->display_cmd?p->display_cmd:"";
   }
}
static int cmp_proc_idx(const void* a,const void* b, void* arg){
   // arg encodes key<<8 | dir etc - we use globals for qsort_r alternative: use static thread-unsafe globals
   (void)a;(void)b;(void)arg; return 0;
}
static int sort_key_global, sort_dir_global;
static int proc_cmp_for_sort(Proc* pa, Proc* pb){
   int key=sort_key_global; int dir=sort_dir_global;
   int cmp=0;
   const FieldDef* d=field_by_id(key);
   int is_string=0;
   if(d){ if(key==1||key==2||key==48||key==112||key==122||key==123||key==124||key==125||key==128||key==129||key==6) is_string=1; }
   if(is_string){ const char* sa=proc_sort_value_str(pa,key); const char* sb=proc_sort_value_str(pb,key); cmp=strcmp(sa,sb); }
   else { double va=proc_sort_value_num(pa,key); double vb=proc_sort_value_num(pb,key); if(va<vb) cmp=-1; else if(va>vb) cmp=1; else cmp=0; }
   if(cmp==0){ if(pa->pid<pb->pid) cmp=-1; else if(pa->pid>pb->pid) cmp=1; return cmp; }
   return dir>=0? cmp : -cmp;
}
static int qsort_cmp_idx(const void* A,const void* B){ int ia=*(const int*)A; int ib=*(const int*)B; return proc_cmp_for_sort(&procs[ia],&procs[ib]); }

static int proc_visible(Proc* p){
   if(cli_user_uid!=-9999 && cli_user_uid>=0 && p->uid!=cli_user_uid) return 0;
   if(!pid_filter_allows(p->pid,p->tgid)) return 0;
   if(S.hide_kernel_threads && p->is_kernel && !p->is_thread) return 0;
   if(S.hide_userland_threads && p->is_thread) return 0;
   if(S.hide_running_in_container && p->is_container) return 0;
   const char* f=active_filter_str?active_filter_str:cli_filter_str;
   if(f && f[0] && !match_filter_terms(p->display_cmd?p->display_cmd:"",f)) return 0;
   return 1;
}

static void build_display_list(void){
   ScreenSettings* sc=cur_screen(); if(!sc) { ndisplay=0; return; }
   // first collect visible indices
   int* idx=xmalloc((nprocs?nprocs:1)*sizeof(int)); int n=0;
   for(int i=0;i<nprocs;i++) if(proc_visible(&procs[i])) idx[n++]=i;
   if(sc->tree_view){
      // build tree
      // map pid->index in visible set (by position in idx)
      // find parent index
      // collapsed handling: we need has_children computed over visible processes
      // Build order via DFS
      int* order=xmalloc((n?n:1)*sizeof(int)); int no=0;
      char* visited=xmalloc(n?n:1); memset(visited,0,n);
      // helper maps: for each visible pos, parent pos or -1
      int* parent=xmalloc((n?n:1)*sizeof(int));
      for(int i=0;i<n;i++){ Proc* p=&procs[idx[i]]; parent[i]=-1;
         int want = p->is_thread? p->tgid : p->ppid;
         // roots for children of PID 1? Original treats processes with ppid of a root (?) In our earlier observations, ppid==1 processes appeared as depth1 under PID 1,
         // so do not special-case ppid==1 as separate root unless that parent is not visible.
         if(want==p->pid) { parent[i]=-1; continue; }
         for(int j=0;j<n;j++){ if(idx[j]==idx[i]) continue; Proc* q=&procs[idx[j]]; if(!q->is_thread && q->pid==want){ parent[i]=j; break; } if(q->is_thread && q->pid==want && want==p->tgid){ parent[i]=j; break; } }
         // if parent is a thread, ignore
         if(parent[i]>=0 && procs[idx[parent[i]]].is_thread) parent[i]=-1;
      }
      // roots sorted by tree sort (or PID if always-by-pid)
      int key,dir; key=sc->tree_sort_key; dir=sc->tree_sort_direction; if(sc->tree_view_always_by_pid){ key=0; dir=1; }
      sort_key_global=key; sort_dir_global=dir;
      // compute has_children
      for(int i=0;i<n;i++){ procs[idx[i]].has_children=0; procs[idx[i]].tree_collapsed=intset_contains(collapsed_pids,ncollapsed,procs[idx[i]].pid); }
      for(int i=0;i<n;i++) if(parent[i]>=0) procs[idx[parent[i]]].has_children=1;
      // if all_branches_collapsed at first build? collapsed set is maintained by user actions; if screen flag set and collapsed list empty, auto-collapse depth1 nodes? handled at toggle/startup separately
      // recursive DFS using explicit stack sorting children each time (n is moderate)
      // Build children lists sorted
      // Simple recursive via function emulation: use iterative stack of frames
      typedef struct {int pos; int child_stage; int* children; int nchild; int cidx; } Frame;
      // first roots list
      int* roots=xmalloc((n?n:1)*sizeof(int)); int nroots=0;
      for(int i=0;i<n;i++) if(parent[i]==-1) roots[nroots++]=i;
      // sort roots (indices into idx, compare proc)
      // Use simple insertion sort with proc_cmp
      for(int i=0;i<nroots;i++) for(int j=i+1;j<nroots;j++){ /* compare idx[roots...] */ int a=idx[roots[i]], b=idx[roots[j]]; if(proc_cmp_for_sort(&procs[b],&procs[a])<0){ int t=roots[i];roots[i]=roots[j];roots[j]=t; } }
      // DFS stack
      typedef struct Frame2 {int pos; int next_child_idx; int* children; int nchild; } Frame2;
      Frame2* stack=xmalloc((n+8)*sizeof(Frame2)); int sp=0;
      // we will push roots in reverse and do pre-order, but children need be generated on entry
      // Use approach: push root frames with state entered flag via sentinel
      // Instead perform recursive simulation with manual stack of iterators and visited marking
      // Simpler: do a loop doing DFS by adding node then pushing a marker? Children need ordering but pre-order alone can be done with stack LIFO.
      int* st=xmalloc((n?n:1)*sizeof(int)); int stn=0;
      for(int i=nroots-1;i>=0;i--) st[stn++]=roots[i];
      // To assign depth/prefix we need path; store depth in a parallel stack
      int* stdepth=xmalloc((n?n:1)*sizeof(int)); // not dynamic separate - we will manage with frames below
      (void)stdepth;
      // Re-implement with frames for correct depth/prefix
      free(st);
      Frame2* fr=xmalloc((n+8)*sizeof(Frame2)); int frn=0;
      // push roots reverse as frames with children not yet computed (next_child_idx=-1)
      for(int i=nroots-1;i>=0;i--){ fr[frn].pos=roots[i]; fr[frn].next_child_idx=-1; fr[frn].children=NULL; fr[frn].nchild=0; frn++; }
      // We also need depth per frame; add via separate array parallel to fr (realloc together is complex) - encode depth in a second stack array
      int* frdepth=xmalloc((n+8)*sizeof(int)); for(int i=0;i<nroots;i++) frdepth[frn-1-i]=0; // roots pushed reverse: fr[0]=last root depth0 etc all zero
      for(int i=0;i<frn;i++) frdepth[i]=0;
      // prefix ancestor info: we compute tree_prefix when node first visited using its parent chain via parent[] and sibling last flags
      // Determine "is last sibling" for each node among its siblings (sorted sibling list same order as children generation)
      // We'll compute sibling groups on demand in a helper manner below by brute force each time in prefix generation (cost ok for moderate n)
      while(frn>0){
         Frame2 cur=fr[frn-1]; int depth=frdepth[frn-1];
         if(cur.next_child_idx==-1){
            // first visit
            if(visited[cur.pos]){ frn--; free(cur.children); continue; }
            visited[cur.pos]=1;
            Proc* p=&procs[idx[cur.pos]]; p->tree_depth=depth;
            // build prefix
            // collect ancestors chain from root to parent
            int chain[128]; int nchain=0; int pp=parent[cur.pos]; while(pp!=-1 && nchain<128){ chain[nchain++]=pp; pp=parent[pp]; }
            // chain is parent, grandparent,... reverse to get ancestors root..parent
            char* pref=NULL; size_t plen=0,pcap=0;
            if(depth>0){
               // segments for ancestors excluding root? We add a segment for each ancestor except the topmost root (depth of ancestor >=1)
               // ancestors in order root->parent: indices chain[nchain-1] .. chain[0]
               for(int ci=nchain-1; ci>=0; ci--){
                  int ancpos=chain[ci]; Proc* anc=&procs[idx[ancpos]]; if(anc->tree_depth==0) continue;
                  // is ancestor last sibling?
                  // determine siblings of anc: nodes with same parent
                  int ancparent=parent[ancpos];
                  // sibling list sorted by current sort: collect and sort by proc_cmp
                  int sib[1024]; int nsib=0; for(int i=0;i<n && nsib<1024;i++) if(parent[i]==ancparent) sib[nsib++]=i;
                  for(int a=0;a<nsib;a++) for(int b=a+1;b<nsib;b++) if(proc_cmp_for_sort(&procs[idx[sib[b]]],&procs[idx[sib[a]]])<0){int t=sib[a];sib[a]=sib[b];sib[b]=t;}
                  int islast = (nsib>0 && sib[nsib-1]==ancpos);
                  strbuf_append(&pref,&plen,&pcap, islast? "   " : "|  ");
               }
               // own segment
               if(p->has_children && p->tree_collapsed) strbuf_append(&pref,&plen,&pcap,"`+ ");
               else strbuf_append(&pref,&plen,&pcap,"`- ");
            } else {
               // root: if collapsed and has children, original shows no prefix in plain for PID1 root (keep empty)
               pref=xstrdup("");
            }
            free(p->tree_prefix); p->tree_prefix=pref?pref:xstrdup("");
            order[no++]=idx[cur.pos];
            // if collapsed, do not expand children
            if(p->has_children && p->tree_collapsed){ frn--; continue; }
            // prepare children
            int* children=xmalloc((n?n:1)*sizeof(int)); int nchild=0;
            for(int i=0;i<n;i++) if(parent[i]==cur.pos) children[nchild++]=i;
            for(int a=0;a<nchild;a++) for(int b=a+1;b<nchild;b++) if(proc_cmp_for_sort(&procs[idx[children[b]]],&procs[idx[children[a]]])<0){int t=children[a];children[a]=children[b];children[b]=t;}
            cur.children=children; cur.nchild=nchild; cur.next_child_idx=0; fr[frn-1]=cur;
            if(nchild==0){ frn--; free(children); continue; }
         }
         // push next child
         if(cur.next_child_idx < cur.nchild){
            int childpos=cur.children[cur.next_child_idx]; cur.next_child_idx++; fr[frn-1]=cur;
            fr[frn].pos=childpos; fr[frn].next_child_idx=-1; fr[frn].children=NULL; fr[frn].nchild=0; frdepth[frn]=depth+1; frn++;
         } else { free(cur.children); frn--; }
      }
      free(fr); free(frdepth); free(stack); free(roots); free(parent); free(visited);
      // any unvisited (cycles) append as roots sorted
      // note visited is freed above - we handled by no check; cycles would be missed but n is moderate and parent chains are trees (ppid cannot cycle except pid=ppid)
      free(idx);
      idx=order; n=no;
      (void)cmp_proc_idx;
   } else {
      int key,dir; key=sc->sort_key; dir=sc->sort_direction;
      sort_key_global=key; sort_dir_global=dir;
      // sort idx using qsort with global comparator (not thread safe but fine)
      // Use insertion? qsort with helper accessing global procs
      // We need a comparator that qsort expects ints; use global via sort_key_global
      // Implement via qsort_r-like using standard qsort and static globals (already)
      extern int qsort_cmp_idx(const void*,const void*);
      qsort(idx,n,sizeof(int),qsort_cmp_idx);
      for(int i=0;i<n;i++){ procs[idx[i]].tree_depth=0; free(procs[idx[i]].tree_prefix); procs[idx[i]].tree_prefix=xstrdup(""); }
   }
   free(display_idx); display_idx=idx; ndisplay=n;
   // display array unused
}
EOF
"}

