static void draw_text_at(int y,int x,const char* s,int attr,int maxw){ if(maxw<0) return; char* tmp=xstrndup(s, maxw); draw_str_attr(y,x,tmp,attr); free(tmp); }

/* function bar drawing */
typedef struct { const char* key; const char* label; } FuncItem;
static void draw_function_bar_items(int y, const FuncItem* items,int n,int pad_override){
   if(y<0||y>=LINES) return; move(y,0); clrtoeol();
