/* meters */
static const char* meter_mode_name(int mode){ switch(mode){case 1:return "Bar";case 2:return "Text";case 3:return "Graph";case 4:return "LED";default:return "Bar";} }
static int parse_cpu_meter(const char* name,int* start,int* count,int* subcols,int* single_idx){
   *single_idx=-1;
   if(starts_with(name,"AllCPUs")){ *start=0; *count=num_cpus; const char* s=name+7; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"LeftCPUs")){ *start=0; *count=(num_cpus+1)/2; const char* s=name+8; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"RightCPUs")){ *start=num_cpus/2; *count=num_cpus-*start; const char* s=name+9; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"CPU")){ // CPU, CPU0, CPU(3)
      const char* s=name+3; int idx=-1; if(s[0]=='(') idx=atoi(s+1); else if(isdigit((unsigned char)s[0])) idx=atoi(s); else idx=-1;
      if(idx>=0){ *single_idx=idx; *start=idx; *count=1; *subcols=1; return 1; }
      // generic CPU meter = all?
      *start=0;*count=num_cpus;*subcols=1; return 1;
   }
   return 0;
}
static int is_cpu_meter(const char* name){ int a,b,c,d; return parse_cpu_meter(name,&a,&b,&c,&d); }
static int meter_height_for(const char* name,int mode,int colwidth){
   (void)mode; (void)colwidth;
   int st,cnt,sub,single; if(parse_cpu_meter(name,&st,&cnt,&sub,&single)){ if(single>=0) return 1; int rows=(cnt+sub-1)/sub; return rows<1?1:rows; }
   return 1;
}
static char* meter_display_name_alloc(const char* name){
   int st,cnt,sub,single; char b[128];
   if(parse_cpu_meter(name,&st,&cnt,&sub,&single)){
      if(single>=0){ snprintf(b,sizeof b,"CPU %d",single + (S.cpu_count_from_one?1:0)); return xstrdup(b); }
      // total subgroups across all cpus split by subcols: compute total blocks = ceil(num_cpus/sub?) Representation uses total sub-columns across split meters:
      // For Left/Right pair, total segments = 16 when sub=8 and cpus=64 (each block is rows count?) The range displayed is in terms of subcolumn blocks: Left (1-8/16), Right (9-16/16)
      int rows = cnt? ( ( ((num_cpus+1)/2) + sub-1)/sub ) : 1; // not for All
      if(starts_with(name,"AllCPUs")){ if(sub==1) snprintf(b,sizeof b,"CPUs (1/1): all CPUs"); else snprintf(b,sizeof b,"CPUs (%s/%d): all CPUs in %d shorter columns", sub==2?"1&2":"1-8", sub==2?2:sub, sub); // setup list only uses detailed in available list, column list short form below overrides
