}
static void format_uptime_str(char* buf,size_t n,unsigned long long secs){
   unsigned long long days=secs/86400; unsigned long long rem=secs%86400; unsigned long long h=rem/3600,m=(rem%3600)/60,s=rem%60;
   if(days>1) snprintf(buf,n,"%llu days, %02llu:%02llu:%02llu",days,h,m,s);
   else if(days==1) snprintf(buf,n,"1 day, %02llu:%02llu:%02llu",h,m,s);
   else snprintf(buf,n,"%02llu:%02llu:%02llu",h,m,s);
}
static void draw_cpu_slot(int y,int x,int width,int cpuidx){
   if(width<=0) return;
   int dispnum=cpuidx + (S.cpu_count_from_one?1:0);
   char label[16]; // width 3 right aligned, or more if >999
   int labelw=3; { int mx=(num_cpus-1)+(S.cpu_count_from_one?1:0); int digits=1; while(mx>=10){mx/=10;digits++;} labelw=digits+1; if(labelw<2)labelw=2; }
