   if(width < labelw+1){ // only label and ]
      char tmp[32]; snprintf(tmp,sizeof tmp,"%s]",labfmt); draw_text_at(y,x,tmp,0,width); return;
   }
   int contentw = width - labelw - 2; // brackets
   if(contentw<0) contentw=0;
   char content[64]; content[0]=0;
   if(contentw==0){ snprintf(content,sizeof content,""); }
   else if(perc<0){ memset(content,' ',contentw); content[contentw]=0; }
   else {
      // percent text adaptive
      char pct[32];
      if(contentw>=7){ snprintf(pct,sizeof pct,"%.1f%%",perc); }
      else { char full[32]; snprintf(full,sizeof full,"%.1f",perc); // truncate to contentw if needed
         if((int)strlen(full)>contentw){ memcpy(pct,full,contentw); pct[contentw]=0; } else snprintf(pct,sizeof pct,"%s",full); }
      // build content: bar fill '|' proportional, then overlay pct at right (when content >=7) or just pct text right aligned/truncated
      for(int i=0;i<contentw;i++) content[i]=' '; content[contentw]=0;
      if(contentw>=7){
         int fill=(int)(perc/100.0*contentw + 0.5); if(fill>contentw) fill=contentw;
         for(int i=0;i<fill;i++) content[i]='|';
         int pl=strlen(pct); int start=contentw-pl; if(start<0) start=0;
         for(int i=0;pct[i] && start+i<contentw;i++) { if(pct[i]!=' ') content[start+i]=pct[i]; }
      } else {
         // show pct text right aligned but if it starts with characters, show truncated from left as original (e.g. "7.", "10")
         char full[32]; snprintf(full,sizeof full,"%.1f",perc);
         if((int)strlen(full)>contentw){ memcpy(content,full,contentw); content[contentw]=0; }
