static void draw_hline_spaces(int y,int x,int w,int attr){ if(y<0||y>=LINES) return; if(x<0){w+=x;x=0;} if(w<=0||x>=COLS) return; if(x+w>COLS) w=COLS-x; attron(attr); move(y,x); for(int i=0;i<w;i++) addch(' '); attroff(attr); }
