      char padded[64]; snprintf(padded,sizeof padded,"%s",lab); int l=strlen(padded); if(i<n-1){ while(l<pad && l<63) padded[l++]=' '; padded[l]=0; }
      draw_str_attr(y,x,padded, mono_mode? A_REVERSE : attr_for_pair(CP_FUNC)); x+=strlen(padded);
      if(x>=COLS) break;
   }
}
static int function_bar_visible(void){ if(S.hide_function_bar==2) return 0; return 1; }

/* meters */
static const char* meter_mode_name(int mode){ switch(mode){case 1:return "Bar";case 2:return "Text";case 3:return "Graph";case 4:return "LED";default:return "Bar";} }
static int parse_cpu_meter(const char* name,int* start,int* count,int* subcols,int* single_idx){
   *single_idx=-1;
   if(starts_with(name,"AllCPUs")){ *start=0; *count=num_cpus; const char* s=name+7; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"LeftCPUs")){ *start=0; *count=(num_cpus+1)/2; const char* s=name+8; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"RightCPUs")){ *start=num_cpus/2; *count=num_cpus-*start; const char* s=name+9; *subcols=s[0]?atoi(s):1; if(*subcols<=0)*subcols=1; return 1; }
   if(starts_with(name,"CPU")){ // CPU, CPU0, CPU(3)
      const char* s=name+3; int idx=-1; if(s[0]=='(') idx=atoi(s+1); else if(isdigit((unsigned char)s[0])) idx=atoi(s); else idx=-1;
      if(idx>=0){ *single_idx=idx; *start=idx; *count=1; *subcols=1; return 1; }
      // generic CPU meter = all?
      *start=0;*count=num_cpus;*subcols=1; return 1;
   }
   return 0;
}
static int is_cpu_meter(const char* name){ int a,b,c,d; return parse_cpu_meter(name,&a,&b,&c,&d); }
static int meter_height_for(const char* name,int mode,int colwidth){
   (void)mode; (void)colwidth;
   int st,cnt,sub,single; if(parse_cpu_meter(name,&st,&cnt,&sub,&single)){ if(single>=0) return 1; int rows=(cnt+sub-1)/sub; return rows<1?1:rows; }
   return 1;
}
static char* meter_display_name_alloc(const char* name){
   int st,cnt,sub,single; char b[128];
   if(parse_cpu_meter(name,&st,&cnt,&sub,&single)){
      if(single>=0){ snprintf(b,sizeof b,"CPU %d",single + (S.cpu_count_from_one?1:0)); return xstrdup(b); }
      // total subgroups across all cpus split by subcols: compute total blocks = ceil(num_cpus/sub?) Representation uses total sub-columns across split meters:
      // For Left/Right pair, total segments = 16 when sub=8 and cpus=64 (each block is rows count?) The range displayed is in terms of subcolumn blocks: Left (1-8/16), Right (9-16/16)
      int rows = cnt? ( ( ((num_cpus+1)/2) + sub-1)/sub ) : 1; // not for All
      if(starts_with(name,"AllCPUs")){ if(sub==1) snprintf(b,sizeof b,"CPUs (1/1): all CPUs"); else snprintf(b,sizeof b,"CPUs (%s/%d): all CPUs in %d shorter columns", sub==2?"1&2":"1-8", sub==2?2:sub, sub); // setup list only uses detailed in available list, column list short form below overrides
         // column list name
         if(sub==1) return xstrdup("CPUs (1/1)");
         else if(sub==2) return xstrdup("CPUs (1&2/2)");
         else if(sub==4) return xstrdup("CPUs (1&2&3&4/4)");
         else { char bb[64]; snprintf(bb,sizeof bb,"CPUs (1-%d/%d)",sub,sub); return xstrdup(bb); }
      }
      if(starts_with(name,"LeftCPUs")){
         if(sub==1) return xstrdup("CPUs (1/2)");
         // total blocks = 2*sub ; left range 1-sub
         char bb[64]; snprintf(bb,sizeof bb,"CPUs (1-%d/%d)",sub,2*sub); (void)rows; return xstrdup(bb);
      }
      if(starts_with(name,"RightCPUs")){
         if(sub==1) return xstrdup("CPUs (2/2)");
         char bb[64]; snprintf(bb,sizeof bb,"CPUs (%d-%d/%d)",sub+1,2*sub,2*sub); return xstrdup(bb);
      }
      return xstrdup("CPUs");
   }
   if(!strcmp(name,"Memory")) return xstrdup("Memory");
   if(!strcmp(name,"Swap")) return xstrdup("Swap");
   if(!strcmp(name,"Tasks")) return xstrdup("Task counter");
   if(!strcmp(name,"LoadAverage")) return xstrdup("Load average");
   if(!strcmp(name,"Load")) return xstrdup("Load");
   if(!strcmp(name,"Uptime")) return xstrdup("Uptime");
   if(!strcmp(name,"Clock")) return xstrdup("Clock");
   if(!strcmp(name,"Date")) return xstrdup("Date");
   if(!strcmp(name,"DateTime")) return xstrdup("Date and Time");
   if(!strcmp(name,"Hostname")) return xstrdup("Hostname");
   if(!strcmp(name,"MemorySwap")||!strcmp(name,"Combined")) return xstrdup("Combined memory and swap usage");
   return xstrdup(name);
}
static void format_uptime_str(char* buf,size_t n,unsigned long long secs){
   unsigned long long days=secs/86400; unsigned long long rem=secs%86400; unsigned long long h=rem/3600,m=(rem%3600)/60,s=rem%60;
   if(days>1) snprintf(buf,n,"%llu days, %02llu:%02llu:%02llu",days,h,m,s);
   else if(days==1) snprintf(buf,n,"1 day, %02llu:%02llu:%02llu",h,m,s);
   else snprintf(buf,n,"%02llu:%02llu:%02llu",h,m,s);
}
static void draw_cpu_slot(int y,int x,int width,int cpuidx){
   if(width<=0) return;
   int dispnum=cpuidx + (S.cpu_count_from_one?1:0);
   char label[16]; // width 3 right aligned, or more if >999
   int labelw=3; { int mx=(num_cpus-1)+(S.cpu_count_from_one?1:0); int digits=1; while(mx>=10){mx/=10;digits++;} labelw=digits+1; if(labelw<2)labelw=2; }
   char labfmt[32]; snprintf(labfmt,sizeof labfmt,"%*d",labelw,dispnum);
   double perc = (cpuidx>=0 && cpuidx<num_cpus && cpu_perc_valid)? cpu_perc[cpuidx+1] : -1;
   if(width < labelw+1){ // only label and ]
      char tmp[32]; snprintf(tmp,sizeof tmp,"%s]",labfmt); draw_text_at(y,x,tmp,0,width); return;
   }
   int contentw = width - labelw - 2; // brackets
   if(contentw<0) contentw=0;
   char content[64]; content[0]=0;
   if(contentw==0){ snprintf(content,sizeof content,""); }
   else if(perc<0){ memset(content,' ',contentw); content[contentw]=0; }
   else {
      // percent text adaptive
      char pct[32];
      if(contentw>=7){ snprintf(pct,sizeof pct,"%.1f%%",perc); }
      else { char full[32]; snprintf(full,sizeof full,"%.1f",perc); // truncate to contentw if needed
         if((int)strlen(full)>contentw){ memcpy(pct,full,contentw); pct[contentw]=0; } else snprintf(pct,sizeof pct,"%s",full); }
      // build content: bar fill '|' proportional, then overlay pct at right (when content >=7) or just pct text right aligned/truncated
      for(int i=0;i<contentw;i++) content[i]=' '; content[contentw]=0;
      if(contentw>=7){
         int fill=(int)(perc/100.0*contentw + 0.5); if(fill>contentw) fill=contentw;
         for(int i=0;i<fill;i++) content[i]='|';
         int pl=strlen(pct); int start=contentw-pl; if(start<0) start=0;
         for(int i=0;pct[i] && start+i<contentw;i++) { if(pct[i]!=' ') content[start+i]=pct[i]; }
      } else {
         // show pct text right aligned but if it starts with characters, show truncated from left as original (e.g. "7.", "10")
         char full[32]; snprintf(full,sizeof full,"%.1f",perc);
         if((int)strlen(full)>contentw){ memcpy(content,full,contentw); content[contentw]=0; }
         else { int pl=strlen(pct); memcpy(content+contentw-pl,pct,pl); }
      }
   }
   // draw: label in cyan, [ default bold, content colored partially - simplify whole
   // label
   draw_str_attr(y,x,labfmt, mono_mode?0:attr_for_pair(CP_METER_LABEL));
