      if(single>=0){ draw_cpu_slot(y,x,width,single); return 1; }
      int rows=(cnt+sub-1)/sub; if(rows<1) rows=1;
      // slot widths distribution
      for(int r=0;r<rows;r++){
         int xx=x;
         for(int c=0;c<sub;c++){
            int remaining_cpus=cnt - c*rows; (void)remaining_cpus;
            int slotw = width/sub; int rem=width%sub; if(c<rem) slotw++;
            // Actually slots are separated by a space in original when slotw>... We'll incorporate space by drawing slot with width-1 and leaving 1 space when not last
            int draww=slotw; if(c<sub-1 && slotw>1){ /* keep as is, next starts after slotw */ }
            int cpupos = st + c*rows + r;
            if(c*rows+r < cnt){ draw_cpu_slot(y+r,xx,draww,cpupos); }
            xx+=slotw;
            if(xx>=x+width) break;
         }
      }
      return rows;
   }
