      unsigned long long cached_eff = mem_cached_kb + sreclaim_kb; if(cached_eff>mem_shared_kb) cached_eff-=mem_shared_kb; else cached_eff=mem_cached_kb;
      unsigned long long used = 0; if(mem_total_kb>mem_free_kb+mem_buffers_kb+cached_eff) used=mem_total_kb-mem_free_kb-mem_buffers_kb-cached_eff;
      if(mode==2){ char u[32],t[32]; format_size_kb(u,sizeof u,used); format_size_kb(t,sizeof t,mem_total_kb); snprintf(buf,sizeof buf,"Mem: %s/%s",u,t); draw_str_attr(y,x,"Mem:",mono_mode?0:attr_for_pair(CP_METER_LABEL)); draw_str(y,x+4,buf+4); return 1; }
      format_size_kb(usedtxt,sizeof usedtxt,used); format_size_kb(totaltxt,sizeof totaltxt,mem_total_kb);
      char txt[64]; snprintf(txt,sizeof txt,"%s/%s",usedtxt,totaltxt);
      int inner=width-5; if(inner<5) inner=5; char innerbuf[512]; for(int i=0;i<inner && i<511;i++) innerbuf[i]=' '; innerbuf[inner<512?inner:511]=0;
      unsigned long long filledval = used + mem_buffers_kb + (S.show_cached_memory? cached_eff:0);
      int fill = mem_total_kb? (int)((double)filledval/(double)mem_total_kb*inner+0.5):0; if(fill>inner) fill=inner;
      for(int i=0;i<fill;i++) innerbuf[i]='|';
      int tl=strlen(txt); int start=inner-tl; if(start<0) start=0; for(int i=0;txt[i] && start+i<inner;i++) if(txt[i]!=' ') innerbuf[start+i]=txt[i];
      draw_str_attr(y,x,"Mem",mono_mode?0:attr_for_pair(CP_METER_LABEL)); char tmp[600]; snprintf(tmp,sizeof tmp,"[%s]",innerbuf); draw_str(y,x+3,tmp); return 1;
   }
   if(!strcmp(name,"Swap")){
      unsigned long long used = swap_total_kb>swap_free_kb? swap_total_kb-swap_free_kb:0;
      if(mode==2){ char u[32],t[32]; format_size_kb(u,sizeof u,used); format_size_kb(t,sizeof t,swap_total_kb); snprintf(buf,sizeof buf,"Swp: %s/%s",u,t); draw_str(y,x,buf); return 1; }
      format_size_kb(usedtxt,sizeof usedtxt,used); format_size_kb(totaltxt,sizeof totaltxt,swap_total_kb);
      char txt[64]; snprintf(txt,sizeof txt,"%s/%s",usedtxt,totaltxt);
      int inner=width-5; if(inner<5) inner=5; char innerbuf[512]; for(int i=0;i<inner && i<511;i++) innerbuf[i]=' '; innerbuf[inner<512?inner:511]=0;
      unsigned long long filledval=used + (S.show_cached_memory?swap_cached_kb:0);
      int fill=swap_total_kb?(int)((double)filledval/(double)swap_total_kb*inner+0.5):0; if(fill>inner) fill=inner; for(int i=0;i<fill;i++) innerbuf[i]='|';
      int tl=strlen(txt); int start=inner-tl; if(start<0) start=0; for(int i=0;txt[i] && start+i<inner;i++) innerbuf[start+i]=txt[i];
      draw_str_attr(y,x,"Swp",mono_mode?0:attr_for_pair(CP_METER_LABEL)); char tmp[600]; snprintf(tmp,sizeof tmp,"[%s]",innerbuf); draw_str(y,x+3,tmp); return 1;
   }
   if(!strcmp(name,"Tasks")){ snprintf(buf,sizeof buf,"Tasks: %d, %d thr, %d kthr; %d running",total_tasks,total_threads_extra,total_kthreads,procs_running); draw_str_attr(y,x,"Tasks:",mono_mode?0:attr_for_pair(CP_METER_LABEL)); char* p=strchr(buf,':'); if(p) draw_str(y,x+6,p+1); else draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"LoadAverage")){ snprintf(buf,sizeof buf,"Load average: %.2f %.2f %.2f",loadavg_vals[0],loadavg_vals[1],loadavg_vals[2]); draw_str_attr(y,x,"Load average:",mono_mode?0:attr_for_pair(CP_METER_LABEL)); char* p=strchr(buf,':'); if(p) draw_str(y,x+13,p+1); else draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Load")){ snprintf(buf,sizeof buf,"Load: %.2f",loadavg_vals[0]); draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Uptime")){ char up[64]; format_uptime_str(up,sizeof up,uptime_secs_ll); snprintf(buf,sizeof buf,"Uptime: %s",up); draw_str_attr(y,x,"Uptime:",mono_mode?0:attr_for_pair(CP_METER_LABEL)); char* p=strchr(buf,':'); if(p) draw_str(y,x+7,p+1); else draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Clock")){ time_t t=time(NULL); struct tm tmv; localtime_r(&t,&tmv); strftime(buf,sizeof buf,"Clock: %H:%M:%S",&tmv); draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Date")){ time_t t=time(NULL); struct tm tmv; localtime_r(&t,&tmv); strftime(buf,sizeof buf,"Date: %Y-%m-%d",&tmv); draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"DateTime")){ time_t t=time(NULL); struct tm tmv; localtime_r(&t,&tmv); strftime(buf,sizeof buf,"Date and Time: %Y-%m-%d %H:%M:%S",&tmv); draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Hostname")){ char hn[256]; gethostname(hn,sizeof hn); snprintf(buf,sizeof buf,"Hostname: %s",hn); draw_str(y,x,buf); return 1; }
   if(!strcmp(name,"Blank")){ return 1; }
   if(!strcmp(name,"System")){ snprintf(buf,sizeof buf,"System: Linux"); draw_str(y,x,buf); return 1; }
   // generic: label + (bar stub)
   { char* dn=meter_display_name_alloc(name); if(mode==1){ int inner=width-(int)strlen(dn)-2; if(inner<3){ draw_text_at(y,x,dn,mono_mode?0:attr_for_pair(CP_METER_LABEL),width); free(dn); return 1; } char tmp[512]; snprintf(tmp,sizeof tmp,"%s[",dn); draw_str_attr(y,x,dn,mono_mode?0:attr_for_pair(CP_METER_LABEL)); draw_str(y,x+strlen(dn),"["); draw_str(y,x+strlen(dn)+1+inner,"]"); free(dn); return 1; } else { draw_text_at(y,x,dn,mono_mode?0:attr_for_pair(CP_METER_LABEL),width); free(dn); return 1; } }
}
