static void format_segment(char* out,size_t outn,const char* val,int width,int align,int is_command){
   if(is_command){ snprintf(out,outn,"%s",val); return; }
   int len=strlen(val);
   if(len>width){
      if(align==ALIGN_LEFT){ snprintf(out,outn,"%.*s",width,val); }
      else snprintf(out,outn,"%s",val); // numeric overflow expands
      return;
   }
   if(align==ALIGN_RIGHT){ snprintf(out,outn,"%*s",width,val); }
   else if(align==ALIGN_LEFT){ snprintf(out,outn,"%-*s",width,val); }
   else { int total=width-len; int left=(total+1)/2; int right=total-left; snprintf(out,outn,"%*s%s%*s",left,"",val,right,""); }
}
