   int effkey,effdir; effkey=effective_sort_key(sc,&effdir);
   for(int i=0;i<sc->nfields;i++){
      const FieldDef* d=field_by_id(sc->fields[i]); if(!d) continue;
      const char* title=d->title; if(d->id==1 && S.show_merged_command) title="Command (merged)";
      int w=d->id==0?pidw:d->width; if(d->id==1) w=strlen(title);
      char seg[256]; format_segment(seg,sizeof seg,title,w,d->align,d->id==1);
      int start=len;
      strbuf_append(&buf,&len,&cap,seg);
