   int list_y=proc_header_y+1;
   int list_h=LINES-list_y-fb; if(list_h<0) list_h=0;
   // clamp selection/scroll
   if(ndisplay==0){ selected_idx=0; list_scroll=0; }
   else { if(selected_idx>=ndisplay) selected_idx=ndisplay-1; if(selected_idx<0) selected_idx=0; }
   if(follow_mode && following_pid>0){ for(int i=0;i<ndisplay;i++) if(procs[display_idx[i]].pid==following_pid){ selected_idx=i; break; } }
   if(selected_idx<list_scroll) list_scroll=selected_idx;
   if(selected_idx>=list_scroll+list_h && list_h>0) list_scroll=selected_idx-list_h+1;
   if(list_scroll<0) list_scroll=0;
   int panel_off=0;
   if(panel_type!=PANEL_NONE) panel_off=panel_width+1;
   // process header
   int ss,sl; char* hdr=build_header_string(&ss,&sl);
   draw_hline_spaces(proc_header_y,panel_off,COLS-panel_off, mono_mode?A_REVERSE:attr_for_pair(CP_HEADER));
   if(scroll_h < (int)strlen(hdr)) {
      // base header
      draw_str_attr(proc_header_y,panel_off,hdr+scroll_h, mono_mode?A_REVERSE:attr_for_pair(CP_HEADER));
      if(ss>=0){ int start=ss-scroll_h; if(start+sl>0 && start<COLS){ int ds=MAX(start,0); int de=MIN(start+sl,COLS-panel_off); if(de>ds){ char* seg=xstrndup(hdr+ss+MAX(0,-start), de-ds); // simpler redraw segment clipped
            // draw sorted segment at correct position
            int segx=panel_off+start; if(segx<panel_off) segx=panel_off;
            // recompute substring
            int src_start=ss; if(start<0) src_start+= -start;
            char* s2=xstrndup(hdr+src_start, de-ds);
            draw_str_attr(proc_header_y,segx,s2, mono_mode?A_REVERSE:attr_for_pair(CP_SEL)); free(s2); free(seg); }
         }
      }
   }
   free(hdr);
   // rows
   for(int row=0;row<list_h;row++){
      int idx=list_scroll+row; int y=list_y+row; if(idx>=ndisplay) break;
      Proc* p=&procs[display_idx[idx]];
      char* rowstr=build_row_string(p);
      int is_sel = (idx==selected_idx);
      int attr=0;
      if(is_sel) attr = (panel_type!=PANEL_NONE)? (mono_mode?A_REVERSE:attr_for_pair(CP_INACTIVE)) : (mono_mode?A_REVERSE:attr_for_pair(CP_SEL));
      else if(intset_contains(tagged_pids,ntagged,p->pid)) attr = A_BOLD | (mono_mode?0:attr_for_pair(CP_YELLOW));
      if(attr) draw_hline_spaces(y,panel_off,COLS-panel_off,attr);
      if(scroll_h < (int)strlen(rowstr)) draw_str_attr(y,panel_off,rowstr+scroll_h,attr);
      free(rowstr);
   }
   // side panel over
   draw_side_panel(proc_header_y,list_y,list_h);
   // function bar / input prompt
   int fy=LINES-1;
   if(fb){
      if(input_mode==MODE_SEARCH){
         FuncItem items[]={{"F3","Next"},{"S-F3","Prev"},{"Esc","Cancel"}}; (void)items;
         // custom: "F3Next  S-F3Prev   EscCancel    Search: xxx"
         move(fy,0); clrtoeol();
         draw_str_attr(fy,0,"F3",0); draw_str_attr(fy,2,"Next",mono_mode?A_REVERSE:attr_for_pair(CP_FUNC)); draw_str(fy,2+4,"  ");
         draw_str_attr(fy,8,"S-F3",0); draw_str_attr(fy,12,"Prev",mono_mode?A_REVERSE:attr_for_pair(CP_FUNC)); draw_str(fy,16,"   ");
         draw_str_attr(fy,19,"Esc",0); draw_str_attr(fy,22,"Cancel",mono_mode?A_REVERSE:attr_for_pair(CP_FUNC)); draw_str(fy,22+6,"    ");
         char prompt[300]; snprintf(prompt,sizeof prompt,"Search: %s",search_buf); draw_str(fy,32,prompt);
      } else if(input_mode==MODE_FILTER){
         move(fy,0); clrtoeol();
         draw_str_attr(fy,0,"Enter",0); draw_str_attr(fy,5,"Done",mono_mode?A_REVERSE:attr_for_pair(CP_FUNC)); draw_str(fy,9,"  ");
         draw_str_attr(fy,11,"Esc",0); draw_str_attr(fy,14,"Clear",mono_mode?A_REVERSE:attr_for_pair(CP_FUNC)); draw_str(fy,19,"    ");
         char prompt[300]; snprintf(prompt,sizeof prompt,"Filter: %s",filter_buf); draw_str(fy,23,prompt);
      } else {
         if(panel_type!=PANEL_NONE){
            const char* lab="Cancel"; const char* firstlab="Set";
            if(panel_type==PANEL_SORT) firstlab="Sort";
            else if(panel_type==PANEL_KILL) firstlab="Send";
            else if(panel_type==PANEL_USER) firstlab="Show";
            else if(panel_type==PANEL_AFFINITY) firstlab="Set";
            else if(panel_type==PANEL_IOPRIO) firstlab="Set";
            else if(panel_type==PANEL_SCHED) firstlab="Select";
            FuncItem items[]={{"Enter",firstlab},{"Esc",lab}};
            draw_function_bar_items(fy,items,2,7);
         } else {
            char* f5lab = (cur_screen() && cur_screen()->tree_view)?"List":"Tree";
            // function labels for readonly blank out Nice/Kill labels
            FuncItem items[]={{"F1","Help"},{"F2","Setup"},{"F3","Search"},{"F4","Filter"},{"F5",f5lab},{"F6","SortBy"},{"F7",cli_readonly?"":"Nice -"},{"F8",cli_readonly?"":"Nice +"},{"F9",cli_readonly?"":"Kill"},{"F10","Quit"}};
            draw_function_bar_items(fy,items,10,0);
         }
      }
   }
   move(LINES-1,COLS-1);
   refresh();
}
EOF
"}

