   if(open_selected<open_scroll) open_scroll=open_selected; if(open_selected>=open_scroll+avail) open_scroll=open_selected-avail+1; if(open_scroll<0)open_scroll=0;
   for(int row=0;row<avail;row++){ int idx=open_scroll+row; if(idx>=open_nlines) break; int y=y0+1+row; int attr=0; if(idx==open_selected && open_nlines>2) attr=mono_mode?A_REVERSE:attr_for_pair(CP_INACTIVE);
