      if(input_mode==MODE_SEARCH || input_mode==MODE_FILTER){ // reuse same bottom prompt drawing as main but over this screen
         // draw a simplified prompt bar
         move(fy,0); clrtoeol(); char pr[300]; if(input_mode==MODE_SEARCH) snprintf(pr,sizeof pr,"Search: %s",search_buf); else snprintf(pr,sizeof pr,"Filter: %s",filter_buf); draw_str(fy,0,pr);
      } else if(open_kind==OPEN_STRACE){
