      if(ch==27){ input_mode=MODE_MAIN; return 0; }
      if(ch=='\n'||ch==KEY_ENTER){ input_mode=MODE_MAIN; return 0; }
      if(ch==KEY_BACKSPACE||ch==127||ch==8){ char* b=input_mode==MODE_SEARCH?search_buf:filter_buf; size_t l=strlen(b); if(l) b[l-1]=0; return 0; }
