      case 27: stop_strace_child(); ui_mode=UI_MAIN; return 0;
      case KEY_UP: if(open_selected>0) open_selected--; return 0;
      case KEY_DOWN: if(open_selected<open_nlines-1) open_selected++; return 0;
      case KEY_PPAGE: open_selected-=10; if(open_selected<0)open_selected=0; return 0;
      case KEY_NPAGE: open_selected+=10; if(open_selected>=open_nlines)open_selected=open_nlines-1; return 0;
      case KEY_HOME: open_selected=0; return 0;
      case KEY_END: open_selected=open_nlines-1; return 0;
      case KEY_F(3): case '/': input_mode=MODE_SEARCH; search_buf[0]=0; return 0;
      case KEY_F(4): case '\\': input_mode=MODE_FILTER; filter_buf[0]=0; return 0;
      case KEY_F(5): build_open_lines(); return 0;
      case KEY_F(8): if(open_kind==OPEN_STRACE) open_autoscroll=!open_autoscroll; return 0;
      case KEY_F(9): if(open_kind==OPEN_STRACE){ if(strace_fp) stop_strace_child(); else build_open_lines(); } return 0;
      default: return 0;
   }
}
