   for(int row=0;row<height;row++){ int idx=*scroll+row; int y=y0+row; if(idx>=n) break; int attr=0; if(idx==selected) attr=(panel==setup_active)?(mono_mode?A_REVERSE:attr_for_pair(CP_SEL)):(mono_mode?0:attr_for_pair(CP_INACTIVE)); if(attr) draw_hline_spaces(y,x,w,attr); draw_text_at(y,x,items[idx],attr,w); }
