/* display option item generation */
static int display_item_is_numeric(int idx){ return idx==29||idx==31||idx==32; }
static void gen_display_items(char*** out,int* outn){
   char** items=NULL; int n=0,cap=0; ScreenSettings* sc=(S.nscreens && setup_display_screen_idx>=0 && setup_display_screen_idx<S.nscreens)? &S.screens[setup_display_screen_idx]:NULL;
   #define ADDIT(s) do{ if(n>=cap){cap=cap?cap*2:40; items=xrealloc(items,cap*sizeof(char*));} items[n++]=xstrdup(s); }while(0)
