   };
   for(size_t i=0;i<sizeof(opts)/sizeof(opts[0]);i++){ snprintf(b,sizeof b,"%s    %s",opts[i].val?"[x]":"[ ]",opts[i].text); ADDIT(b); }
   snprintf(b,sizeof b,"[%.1f]  Update interval (in seconds)",S.delay/10.0); ADDIT(b);
   snprintf(b,sizeof b,"%s    Highlight new and old processes",S.highlight_changes?"[x]":"[ ]"); ADDIT(b);
   snprintf(b,sizeof b,"[%d]    - Highlight time (in seconds)",S.highlight_changes_delay_secs); ADDIT(b);
   snprintf(b,sizeof b,"[%d]    Hide main function bar (0 - off, 1 - on ESC until next input, 2 - permanently)",S.hide_function_bar); ADDIT(b);
