   // categories always
   { char* items[5]; for(int i=0;i<5;i++) items[i]=(char*)SETUP_CATEGORIES[i]; int scroll=0; // category scroll kept in a static via a hack: use setup_display_scroll? Use local persist via global? We store category panel scroll in a dedicated variable below (reuse setup_screens_scroll? no)
      static int cat_scroll=0; (void)cat_scroll;
