         char** items=NULL; int n=0; if(c<S.nmeter_cols) n=S.nmeters[c]; items=xmalloc((n?n:1)*sizeof(char*));
         for(int i=0;i<n;i++){ if(!strcmp(S.meters[c][i],"!")){ items[i]=xstrdup(""); continue; } char* dn=meter_display_name_alloc(S.meters[c][i]); char b[256]; if(setup_moving && setup_moving_col==c && setup_moving_idx==i) snprintf(b,sizeof b,"+ %s [%s]",dn,meter_mode_name(S.meter_modes[c]?S.meter_modes[c][i]:1)); else snprintf(b,sizeof b,"%s [%s]",dn,meter_mode_name(S.meter_modes[c]?S.meter_modes[c][i]:1)); free(dn); items[i]=xstrdup(b); }
         int sel=setup_mcol_sel[c]; if(sel>=n && n>0) sel=n-1; if(sel<0) sel=0; setup_mcol_sel[c]=sel;
         setup_draw_panel_items(c+1,y0+1,height,items,n,sel,&setup_mcol_scroll[c]);
