static void toggle_display_item(int idx,int how){ // how: 0 toggle/select, +1 inc, -1 dec
   ScreenSettings* sc=(S.nscreens && setup_display_screen_idx>=0 && setup_display_screen_idx<S.nscreens)? &S.screens[setup_display_screen_idx]:NULL;
   S.changed=1;
   if(idx==0){ if(S.nscreens) setup_display_screen_idx=(setup_display_screen_idx+1)%S.nscreens; return; }
   if(idx==1 && sc){ sc->tree_view=!sc->tree_view; return; }
   if(idx==2 && sc){ sc->tree_view_always_by_pid=!sc->tree_view_always_by_pid; return; }
   if(idx==3 && sc){ sc->all_branches_collapsed=!sc->all_branches_collapsed; return; }
   if(idx==4) return;
   // map global opts indices 5..28
   int* ptr=NULL;
   switch(idx){
      case 5: ptr=&S.screen_tabs; break; case 6: ptr=&S.shadow_other_users; break; case 7: ptr=&S.hide_kernel_threads; break; case 8: ptr=&S.hide_userland_threads; break; case 9: ptr=&S.hide_running_in_container; break; case 10: ptr=&S.highlight_threads; break; case 11: ptr=&S.show_thread_names; break; case 12: ptr=&S.show_program_path; break; case 13: ptr=&S.highlight_base_name; break; case 14: ptr=&S.highlight_deleted_exe; break; case 15: ptr=&S.shadow_distribution_path_prefix; break; case 16: ptr=&S.show_merged_command; break; case 17: ptr=&S.find_comm_in_cmdline; break; case 18: ptr=&S.strip_exe_from_cmdline; break; case 19: ptr=&S.highlight_megabytes; break; case 20: ptr=&S.header_margin; break; case 21: ptr=&S.detailed_cpu_time; break; case 22: ptr=&S.cpu_count_from_one; break; case 23: ptr=&S.update_process_names; break; case 24: ptr=&S.account_guest_in_cpu_meter; break; case 25: ptr=&S.show_cpu_usage; break; case 26: ptr=&S.show_cpu_frequency; break; case 27: ptr=&S.show_cached_memory; break; case 28: ptr=&S.enable_mouse; break;
      case 29: { if(how>0) S.delay++; else if(how<0) S.delay--; else S.delay++; if(S.delay<1)S.delay=1; if(S.delay>100)S.delay=100; return; }
      case 30: ptr=&S.highlight_changes; break;
      case 31: { if(how>0) S.highlight_changes_delay_secs++; else if(how<0) S.highlight_changes_delay_secs--; else S.highlight_changes_delay_secs++; if(S.highlight_changes_delay_secs<1)S.highlight_changes_delay_secs=1; return; }
      case 32: { if(how>0) S.hide_function_bar++; else if(how<0) S.hide_function_bar--; else S.hide_function_bar++; if(S.hide_function_bar<0)S.hide_function_bar=0; if(S.hide_function_bar>2)S.hide_function_bar=2; return; }
   }
   if(ptr) *ptr=!*ptr;
   // side effects requiring new avail meters list for cpu counting
   if(idx==22){ navail_meters=0; build_avail_meters(); }
}
static void apply_layout_change(int idx){
   if(idx<0||idx>=(int)(sizeof(LAYOUT_OPTS)/sizeof(LAYOUT_OPTS[0]))) return;
   const char* ns=LAYOUT_OPTS[idx].str; int newn=header_layout_cols(ns); int oldn=header_layout_cols(S.header_layout);
   S.changed=1;
   if(newn>oldn){
      ensure_meter_cols(); // extends S.nmeter_cols to new? ensure uses header_layout still old; do manual growth
      if(newn>S.nmeter_cols){ S.meters=xrealloc(S.meters,newn*sizeof(char**)); S.nmeters=xrealloc(S.nmeters,newn*sizeof(int)); S.meter_modes=xrealloc(S.meter_modes,newn*sizeof(int*)); for(int i=S.nmeter_cols;i<newn;i++){ S.meters[i]=xmalloc(sizeof(char*)); S.meters[i][0]=xstrdup("!"); S.nmeters[i]=1; S.meter_modes[i]=xmalloc(sizeof(int)); S.meter_modes[i][0]=0; } S.nmeter_cols=newn; }
   } else if(newn<oldn){
      // move removed cols meters reversed into last remaining col
      for(int c=oldn-1;c>=newn;c--){
         if(c<S.nmeter_cols){
            for(int i=S.nmeters[c]-1;i>=0;i--){ if(!strcmp(S.meters[c][i],"!")) continue; int dst=newn-1; S.meters[dst]=xrealloc(S.meters[dst],(S.nmeters[dst]+1)*sizeof(char*)); S.meter_modes[dst]=xrealloc(S.meter_modes[dst],(S.nmeters[dst]+1)*sizeof(int)); S.meters[dst][S.nmeters[dst]]=S.meters[c][i]; S.meter_modes[dst][S.nmeters[dst]]=S.meter_modes[c]?S.meter_modes[c][i]:1; S.nmeters[dst]++; }
         }
      }
   }
   free(S.header_layout); S.header_layout=xstrdup(ns);
