/* parsing helper: C strtol style, returns 0 if no conversion */
static int parse_htop_int(const char* s,int* out){
   if(!s) return 0; char* end=NULL; errno=0; long v=strtol(s,&end,10); if(end==s) return 0; *out=(int)(unsigned int)v; return 1;
}
static int resolve_user_cli(const char* s,long* out){
   struct passwd* pw=getpwnam(s); if(pw){ *out=(long)pw->pw_uid; return 1; }
   char* end=NULL; errno=0; long v=strtol(s,&end,10); if(end==s||!end||*end||errno) return 0; if(v<0 || (unsigned long)v>4294967295UL) return 0; *out=v; return 1;
}

enum { OPT_NOMETERS=1000, OPT_NOFUNCBAR=1001, OPT_READONLY=1002 };
int main(int argc,char* argv[]){
   setlocale(LC_ALL,"");
   hz=sysconf(_SC_CLK_TCK); if(hz<=0) hz=100; long ps=sysconf(_SC_PAGESIZE); page_kb=ps>0? ps/1024:4; if(page_kb<=0)page_kb=4;
   // CLI parsing using getopt_long (option order matches reference for ambiguous messages)
   static struct option long_opts[]={
      {"help",no_argument,0,'h'},
      {"version",no_argument,0,'V'},
      {"delay",required_argument,0,'d'},
      {"max-iterations",required_argument,0,'n'},
      {"sort-key",required_argument,0,'s'},
      {"user",optional_argument,0,'u'},
      {"no-color",no_argument,0,'C'},
      {"no-colour",no_argument,0,'C'},
      {"no-mouse",no_argument,0,'M'},
      {"no-unicode",no_argument,0,'U'},
      {"no-meters",no_argument,0,OPT_NOMETERS},
      {"tree",no_argument,0,'t'},
      {"pid",required_argument,0,'p'},
      {"filter",required_argument,0,'F'},
      {"no-functionbar",no_argument,0,OPT_NOFUNCBAR},
      {"no-function-bar",no_argument,0,OPT_NOFUNCBAR},
      {"highlight-changes",optional_argument,0,'H'},
      {"readonly",no_argument,0,OPT_READONLY},
      {0,0,0,0}
   };
   const char* prog=argv[0];
   (void)prog;
   int cli_sort_specified=0;
   int ch;
   // getopt_long prints errors itself using argv[0]
   while((ch=getopt_long(argc,argv,"Cd:F:hH::Mn:p:s:tu::UV",long_opts,NULL))!=-1){
      switch(ch){
         case 'h': print_help(); return 0;
         case 'V': printf("htop " VERSION_STR "\n"); return 0;
         case 'd': { int v; if(!parse_htop_int(optarg,&v)){ fprintf(stderr,"Error: invalid delay value \"%s\".\n",optarg); return 1; } if(v<1)v=1; if(v>100)v=100; cli_delay=v; break; }
         case 'n': { int v; if(!parse_htop_int(optarg,&v)){ fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",optarg); return 1; } if(v<=0){ fprintf(stderr,"Error: maximum iteration count must be positive.\n"); return 1; } cli_max_iterations=v; break; }
         case 's': {
            if(!strcmp(optarg,"help")){ print_sort_help(); return 0; }
