            cli_sort_id=d->id; cli_sort_specified=1; break; }
         case 'u': {
            const char* arg=optarg;
            if(!arg && optind<argc && argv[optind] && argv[optind][0] && argv[optind][0]!='-'){ arg=argv[optind++]; }
