            const char* pstr=optarg; const char* start=pstr;
            while(1){ const char* comma=strchr(start,','); size_t len=comma?(size_t)(comma-start):strlen(start); char tok[128]; if(len>=sizeof tok) len=sizeof tok-1; memcpy(tok,start,len); tok[len]=0; int pidv=atoi(tok); cli_pids=xrealloc(cli_pids,(cli_npids+1)*sizeof(int)); cli_pids[cli_npids++]=pidv; if(!comma) break; start=comma+1; }
            break; }
         case 'F': if(!optarg || !optarg[0]){ fprintf(stderr,"Error: invalid filter value \"%s\".\n",optarg?optarg:""); return 1; } free(cli_filter_str); cli_filter_str=xstrdup(optarg); break;
         case OPT_NOFUNCBAR: cli_no_function_bar=1; break;
         case 'H': {
            cli_highlight=1;
            const char* arg=optarg;
            if(!arg && optind<argc && argv[optind] && argv[optind][0] && argv[optind][0]!='-'){ arg=argv[optind++]; }
            if(arg){ int v; if(!parse_htop_int(arg,&v)){ fprintf(stderr,"Error: invalid highlight delay value \"%s\".\n",arg); return 1; } if(v<1)v=1; cli_highlight_delay=v; }
            break; }
         case OPT_READONLY: cli_readonly=1; break;
         case '?': default: return 1;
      }
   }
   if(optind<argc){
      fprintf(stderr,"Error: unsupported non-option ARGV-elements:");
      for(int i=optind;i<argc;i++) fprintf(stderr," %s",argv[i]);
      fprintf(stderr,"\n");
      return 1;
   }
   (void)cli_sort_specified;
   // Load settings and apply CLI overrides
   settings_read();
   if(cli_delay>=0) S.delay=cli_delay;
   if(cli_mouse_disable) S.enable_mouse=0;
   if(cli_no_function_bar) S.hide_function_bar=2;
   if(cli_highlight>=0 && cli_highlight){ S.highlight_changes=1; if(cli_highlight_delay>0) S.highlight_changes_delay_secs=cli_highlight_delay; }
   if(S.nscreens>0){
      ScreenSettings* first=&S.screens[0];
      if(cli_tree_flag) first->tree_view=1;
      if(cli_sort_id>=0){
         const FieldDef* d=field_by_id(cli_sort_id);
         if(cli_tree_flag){ if(first->tree_sort_key!=cli_sort_id){ first->tree_sort_key=cli_sort_id; if(d) first->tree_sort_direction=d->defdir; } }
         else { if(first->sort_key!=cli_sort_id){ first->sort_key=cli_sort_id; if(d) first->sort_direction=d->defdir; } first->tree_view=0; }
      }
