   filter_ptr_global=cli_filter_str; active_filter_str=cli_filter_str;
   current_screen_idx=0;
   if(S.nscreens>0){ all_collapse_active_global=S.screens[0].all_branches_collapsed && S.screens[0].tree_view; }
   setup_display_screen_idx=0;
   // terminal check
   { const char* term_env=getenv("TERM"); const char* term_disp=(term_env&&term_env[0])?term_env:"unknown"; int errret=0; if(setupterm((char*)(term_env?term_env:"unknown"),STDOUT_FILENO,&errret)==ERR){ fprintf(stderr,"Error opening terminal: %s.\n",term_disp); return 1; } }
