   scan_processes(); build_display_list();
   int iteration=0;
   int signal_exit=0;
   quit_requested=0;
   while(1){
      if(got_signal){ signal_exit=got_signal; break; }
      if(ui_mode==UI_MAIN && !paused_updates){ /* scan already at loop bottom? We'll scan at top each iteration */ }
      // scan unless paused (but always scan first iteration handled)
      if(iteration>0 && !paused_updates){ scan_processes(); }
      build_display_list();
      iteration++;
      if(ui_mode==UI_HELP) draw_help();
      else if(ui_mode==UI_SETUP) draw_setup();
      else if(ui_mode==UI_OPEN) draw_open_screen();
      else draw_main();
      if(cli_max_iterations>0 && iteration>=cli_max_iterations) break;
      if(got_signal){ signal_exit=got_signal; break; }
      int delay_ms = S.delay*100; if(delay_ms<10) delay_ms=100; // S.delay is tenths
      timeout(delay_ms);
      int c=getch();
      if(c==ERR){
         if(got_signal){ signal_exit=got_signal; break; }
         // stdin EOF / closed check for non-tty
         if(!isatty(STDIN_FILENO)){
            // if stdin is EOF, exit cleanly after at least one frame
            if(feof(stdin)) break;
            struct pollfd {int fd; short events; short revents;} ; (void)0;
            // use poll() via poll.h not included; fallback: if stdin fd is at EOF via read peek is risky, so break if stdin is /dev/null detected by fstat size? Instead rely on feof
            // Additional: if getch repeatedly returns ERR due EOF, curses sets feof
            break;
         }
         continue;
      }
      if(c==KEY_RESIZE){ clear(); continue; }
