            if(ui_mode==UI_MAIN && panel_type==PANEL_NONE){
               int tabs=-1; int hdr=hide_meters_runtime?0:compute_header_rows(&tabs,NULL); int list_y=hdr+1; int fb=function_bar_visible()?1:0; int lh=LINES-list_y-fb;
               if(ev.y>=list_y && ev.y<list_y+lh){ int idx=list_scroll+(ev.y-list_y); if(idx<ndisplay) selected_idx=idx; }
               else if(ev.y==hdr){
                  // click on column header: sort by field at x
                  // build header positions: approximate by finding field whose segment contains x+scroll_h
                  // Build segments
                  ScreenSettings* sc=cur_screen(); int pidw=current_pid_width(); int pos=0; int clickx=ev.x+scroll_h;
                  if(sc){ for(int i=0;i<sc->nfields;i++){ const FieldDef* d=field_by_id(sc->fields[i]); if(!d) continue; int w=d->id==0?pidw:d->width; if(d->id==1) w=10000; int segw=w + (i<sc->nfields-1?1:0); if(clickx>=pos && clickx<pos+segw){ set_sort_action(d->id,1); break; } pos+=segw; } }
               } else if(ev.y==LINES-1 && fb){
                  // function bar approximate: each item 8 chars
                  int item=ev.x/8; if(item==0) ui_mode=UI_HELP; else if(item==1){ ui_mode=UI_SETUP; setup_display_screen_idx=current_screen_idx; } else if(item==2){ input_mode=MODE_SEARCH; search_buf[0]=0; } else if(item==3){ input_mode=MODE_FILTER; } else if(item==4){ ScreenSettings* sc=cur_screen(); if(sc){sc->tree_view=!sc->tree_view; S.changed=1;} } else if(item==5) open_sort_panel(); else if(item==6) do_nice_action(-1); else if(item==7) do_nice_action(1); else if(item==8) open_kill_panel(); else if(item>=9) { quit_requested=1; }
               }
            }
         }
         if(quit_requested) break;
         continue;
      }
      if(ui_mode==UI_HELP){ help_key(c); continue; }
      if(ui_mode==UI_SETUP){ setup_key(c); continue; }
      if(ui_mode==UI_OPEN){ open_screen_key(c); continue; }
      // main mode
      int was_temp = temp_funcbar_global;
      main_key(c);
      if(was_temp && c!=27) temp_funcbar_global=0;
      if(quit_requested) break;
      if(got_signal){ signal_exit=got_signal; break; }
   }
   endwin();
   if(signal_exit){
      printf("A signal %d (%s) was received, exiting without persisting settings to htoprc.\n",signal_exit,strsignal(signal_exit)?strsignal(signal_exit):"Unknown");
      fflush(stdout);
      return 0;
   }
   settings_write();
   return 0;
}
