                  ScreenSettings* sc=cur_screen(); int pidw=current_pid_width(); int pos=0; int clickx=ev.x+scroll_h;
                  if(sc){ for(int i=0;i<sc->nfields;i++){ const FieldDef* d=field_by_id(sc->fields[i]); if(!d) continue; int w=d->id==0?pidw:d->width; if(d->id==1) w=10000; int segw=w + (i<sc->nfields-1?1:0); if(clickx>=pos && clickx<pos+segw){ set_sort_action(d->id,1); break; } pos+=segw; } }
               } else if(ev.y==LINES-1 && fb){
                  int item=ev.x/8; if(item==0) ui_mode=UI_HELP; else if(item==1){ ui_mode=UI_SETUP; setup_display_screen_idx=current_screen_idx; } else if(item==2){ input_mode=MODE_SEARCH; search_buf[0]=0; } else if(item==3){ input_mode=MODE_FILTER; } else if(item==4){ ScreenSettings* sc=cur_screen(); if(sc){sc->tree_view=!sc->tree_view; S.changed=1; force_rescan_flag=1;} } else if(item==5) open_sort_panel(); else if(item==6) do_nice_action(-1); else if(item==7) do_nice_action(1); else if(item==8) open_kill_panel(); else if(item>=9) { quit_requested=1; }
               }
            }
         }
         if(quit_requested) break;
         if(force_rescan_flag && !paused_updates){ scan_processes(); iteration++; next_scan=now_double()+(S.delay>0?S.delay:15)/10.0; force_rescan_flag=0; }
         continue;
      }
      if(ui_mode==UI_HELP){ help_key(c); continue; }
      if(ui_mode==UI_SETUP){ int before_setup=(ui_mode==UI_SETUP); setup_key(c); (void)before_setup; if(ui_mode==UI_MAIN) force_rescan_flag=1; if(force_rescan_flag && !paused_updates){ scan_processes(); iteration++; next_scan=now_double()+(S.delay>0?S.delay:15)/10.0; force_rescan_flag=0; } continue; }
      if(ui_mode==UI_OPEN){ open_screen_key(c); continue; }
      int was_temp = temp_funcbar_global;
      // keys that should refresh data after acting
      int key_before_tab = current_screen_idx;
      main_key(c);
      if(current_screen_idx!=key_before_tab) force_rescan_flag=1;
      if(was_temp && c!=27) temp_funcbar_global=0;
      if(quit_requested) break;
      if(got_signal){ signal_exit=got_signal; break; }
      if(force_rescan_flag && !paused_updates){ scan_processes(); iteration++; next_scan=now_double()+(S.delay>0?S.delay:15)/10.0; force_rescan_flag=0; }
   }
'''
