import pty, os, subprocess, time, fcntl, termios, struct, signal
for bin in ["./executable","/tmp/myhtop"]:
    pid, fd = pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm"; os.environ["HTOPRC"]="/tmp/tmprc_zero"
        os.execv(bin if bin.startswith("/") else os.path.join(os.getcwd(),bin[2:]), [bin,"--no-meters","-n","2","-d","1"])
    else:
        # set winsize 0
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH",0,0,0,0))
        time.sleep(2)
        alive=True
        try:
            r=os.waitpid(pid, os.WNOHANG)
        except Exception as e: print(e)
        print(bin,"wait",r)
        if r==(0,0):
            os.kill(pid, signal.SIGTERM); time.sleep(.5); print(os.waitpid(pid,0))
        try: os.close(fd)
        except: pass
