{"command":"cat > /tmp/patch_strace.py <<'PY'
import pathlib
p=pathlib.Path("src/htop.c"); s=p.read_text()
# replace strace_fp handling in stop function to waitpid
s=s.replace('''static void stop_strace_child(void){ if(strace_fp){ fclose(strace_fp); strace_fp=NULL; } if(strace_pid>0){ kill(strace_pid,SIGTERM); strace_pid=0; } }''',
'''static void stop_strace_child(void){ if(strace_pid>0){ kill(strace_pid,SIGTERM); }
   if(strace_fp){ fclose(strace_fp); strace_fp=NULL; }
   if(strace_pid>0){ int st; waitpid(strace_pid,&st,0); strace_pid=0; } }''')
# Replace popen block in build_open_lines strace branch
old='''      } else {
         char cmd[256]; snprintf(cmd,sizeof cmd,"strace -f -p %d 2>&1",open_pid); strace_fp=popen(cmd,"r"); if(!strace_fp){ open_add_line("Could not execute 'strace'. Please make sure it is available in your $PATH."); }
         else { strace_pid=0; /* popen child pid not directly known; reading in draw would block - we read nonblocking in key loop via fileno flags */ int fd=fileno(strace_fp); int flags=fcntl(fd,F_GETFL,0); fcntl(fd,F_SETFL,flags|O_NONBLOCK); }
      }'''
new='''      } else {
         stop_strace_child();
         int pipefd[2]; if(pipe(pipefd)!=0){ open_add_line("Could not execute 'strace'. Please make sure it is available in your $PATH."); }
         else { pid_t child=fork(); if(child==0){ close(pipefd[0]); dup2(pipefd[1],1); dup2(pipefd[1],2); close(pipefd[1]); char pidstr[32]; snprintf(pidstr,sizeof pidstr,"%d",open_pid); execlp("strace","strace","-f","-p",pidstr,(char*)NULL); _exit(127); }
            close(pipefd[1]); strace_pid=child; strace_fp=fdopen(pipefd[0],"r"); if(strace_fp){ int fd=fileno(strace_fp); int flags=fcntl(fd,F_GETFL,0); fcntl(fd,F_SETFL,flags|O_NONBLOCK); } }
      }'''
assert old in s; s=s.replace(old,new)
p.write_text(s)
print("ok")
PY
python3 /tmp/patch_strace.py
cc -O2 -o /tmp/myhtop src/htop.c -lncursesw -lm >/tmp/compile.log 2>&1; echo exit:$?; grep error /tmp/compile.log | head
which strace || echo "no strace as expected""}

